    #[test]
    fn server_hello_and_tablet_result_same_poll_keep_host_result_authoritative() {
        let generation = 17;
        let mut app = ArcenApp {
            connection_generation: generation,
            tablet_mode_requested: TabletModeMsg::WacomUsbBridge,
            tablet_mode_active: TabletModeMsg::WacomUsbBridge,
            tablet_input_enabled: false,
            ..ArcenApp::default()
        };
        let hello: ServerHelloMsg = serde_json::from_value(serde_json::json!({
            "type": "server_hello",
            "input_protocol_version": crate::protocol::messages::INPUT_PROTOCOL_VERSION,
            "input_capabilities": {"pen": "available"},
            "tablet_mode_capabilities": {
                "local_termination": "available",
                "wacom_usb_bridge": "unavailable",
                "disabled_mouse_compat": "available"
            }
        }))
        .unwrap();
        let reason = "native bridge unavailable";
        let shared = Arc::new(Mutex::new(SharedMediaState {
            server_hello: Some(hello),
            tablet_mode_result: Some(TabletModeResultMsg {
                requested: TabletModeMsg::WacomUsbBridge,
                active: TabletModeMsg::DisabledMouseCompat,
                accepted: false,
                reason: TabletModeReason::try_from(reason.to_string()).unwrap(),
                reconnect_required: true,
                ..TabletModeResultMsg::default()
            }),
            generation,
            ..SharedMediaState::default()
        }));
        app.media = Some(shared);

        app.sync_media_state(&egui::Context::default());

        assert_eq!(app.tablet_mode_active, TabletModeMsg::DisabledMouseCompat);
        assert_eq!(app.tablet_mode_reason, reason);
        assert!(!app.tablet_input_enabled);
        assert!(!app.pen_negotiated);
    }

