    #[test]
    fn microphone_indicator_waits_for_transport_cleanup_confirmation() {
        let (mut app, _receiver) = app_with_command_channel();
        let shared = Arc::new(Mutex::new(SharedMediaState::fresh(
            app.connection_generation,
            false,
        )));
        shared.lock().unwrap().microphone_active = true;
        app.media = Some(Arc::clone(&shared));
        app.microphone_active = true;

        app.disconnect();
        assert!(app.microphone_active);
        assert!(!app.microphone_teardown.is_empty());

        {
            let mut state = shared.lock().unwrap();
            state.microphone_active = false;
            state.closed = true;
        }
        app.poll_microphone_teardown();
        assert!(!app.microphone_active);
        assert!(app.microphone_teardown.is_empty());
    }

    #[test]
    fn pending_microphone_start_retains_indicator_until_transport_closes() {
        let (mut app, _receiver) = app_with_command_channel();
        let shared = Arc::new(Mutex::new(SharedMediaState::fresh(
            app.connection_generation,
            false,
        )));
        app.session_commands
            .as_ref()
            .unwrap()
            .set_microphone_lifecycle_for_test(true);
        app.media = Some(Arc::clone(&shared));

        app.disconnect();
        assert!(app.microphone_active);
        assert!(!app.microphone_teardown.is_empty());

        shared.lock().unwrap().closed = true;
        app.poll_microphone_teardown();
        assert!(!app.microphone_active);
        assert!(app.microphone_teardown.is_empty());
    }

    #[test]
    fn overlapping_session_teardowns_keep_indicator_until_all_close() {
        let mut app = ArcenApp::default();
        let first = Arc::new(Mutex::new(SharedMediaState::fresh(1, false)));
        let second = Arc::new(Mutex::new(SharedMediaState::fresh(2, false)));
        app.microphone_teardown = vec![Arc::clone(&first), Arc::clone(&second)];
        app.microphone_active = true;

        first.lock().unwrap().closed = true;
        app.poll_microphone_teardown();
        assert!(app.microphone_active);
        assert_eq!(app.microphone_teardown.len(), 1);

        second.lock().unwrap().closed = true;
        app.poll_microphone_teardown();
        assert!(!app.microphone_active);
        assert!(app.microphone_teardown.is_empty());
    }

    fn receive_json(receiver: &mut mpsc::UnboundedReceiver<SessionCommand>) -> serde_json::Value {
        match receiver.try_recv().expect("queued session command") {
            SessionCommand::Json(value) => value,
            SessionCommand::SubmitAuth(_)
            | SessionCommand::AcceptAuthentication
            | SessionCommand::DeclineDisclaimer
            | SessionCommand::Binary(_)
            | SessionCommand::HardUsbPen(_)
            | SessionCommand::Close => panic!("expected JSON command"),
        }
    }

    fn assert_direct_region_json(value: &serde_json::Value) {
        let message_type = value["type"].as_str().expect("region command type");
        assert!(
            message_type.starts_with("region_pointer_") || message_type == "region_pen_event",
            "expected direct Region* command, got {value:?}",
        );
        let object = value.as_object().expect("region command object");
        assert!(!object.contains_key("server_x"));
        assert!(!object.contains_key("server_y"));
    }

    fn receive_region_json(
        receiver: &mut mpsc::UnboundedReceiver<SessionCommand>,
        expected_type: &str,
    ) -> serde_json::Value {
        loop {
            let value = receive_json(receiver);
            assert_direct_region_json(&value);
            if value["type"] == expected_type {
                return value;
            }
        }
    }

    fn seed_non_modifier_and_modifier(
        app: &mut ArcenApp,
        receiver: &mut mpsc::UnboundedReceiver<SessionCommand>,
    ) {
        app.process_keyboard_event(&key_event(
            egui::Key::ShiftLeft,
            true,
            egui::Modifiers::SHIFT,
        ));
        app.process_keyboard_event(&key_event(egui::Key::A, true, egui::Modifiers::SHIFT));
        assert_eq!(receive_json(receiver)["pressed"], true);
        assert_eq!(receive_json(receiver)["pressed"], true);
        assert_eq!(app.keyboard.held_count(), 2);
    }

    fn assert_releases_before_reset(
        receiver: &mut mpsc::UnboundedReceiver<SessionCommand>,
        reason: &str,
    ) {
        let non_modifier_release = receive_json(receiver);
        assert_eq!(non_modifier_release["type"], "key_event");
        assert_eq!(non_modifier_release["scan_code"], 0x41);
        assert_eq!(non_modifier_release["pressed"], false);

        let modifier_release = receive_json(receiver);
        assert_eq!(modifier_release["type"], "key_event");
        assert_eq!(modifier_release["scan_code"], 0x0100_0020_u32);
        assert_eq!(modifier_release["pressed"], false);

        let reset = receive_json(receiver);
        assert_eq!(reset["type"], "key_reset_modifiers");
        assert_eq!(reset["reason"], reason);
    }

