        assert_eq!(press["modifiers"], 0x0F);
        assert_eq!(press["server_x"], -1);
        assert_eq!(press["server_y"], -1);
        assert_eq!(press["coalescable"], false);
        assert!(press["sequence"].as_u64().unwrap() > 0);
        assert!(press["timestamp_ns"].as_u64().unwrap() > 0);
        assert!(press.get("caps_lock_on").is_none());
        assert!(press.get("num_lock_on").is_none());
        assert!(press.get("scroll_lock_on").is_none());

        let release = receive_json(&mut receiver);
        assert_eq!(release["scan_code"], 0x41);
        assert_eq!(release["pressed"], false);
