    #[test]
    fn secondary_viewport_focus_loss_releases_held_keys_before_modifier_reset() {
        // Finding #3: a secondary viewport genuinely holding OS keyboard
        // focus (root's own `viewer_focused` flag is necessarily `false`
        // at the same time, but that must never reach
        // `update_viewer_keyboard_focus` directly -- root's own call site
        // now always combines it with `active_secondary_keyboard_focus`
        // first) must still release every held key exactly once when
        // focus genuinely leaves *every* one of our own viewports (e.g.
        // the whole app loses focus to another application entirely).
        let (mut app, mut receiver) = app_with_command_channel();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        seed_non_modifier_and_modifier(&mut app, &mut receiver);
        app.pointer_lock = true;

        app.sync_keyboard_focus_across_viewports(None);

        assert_releases_before_reset(&mut receiver, "focus_out");
        assert_eq!(app.keyboard.held_count(), 0);
        assert!(!app.pointer_lock);
        assert!(!app.keyboard.focused());
        assert!(app.active_keyboard_viewport.is_none());
    }

    #[test]
    fn switching_between_two_secondary_viewports_releases_held_keys_exactly_once() {
        // Finding #3: an internal viewport switch (secondary -> a
        // different secondary) never drops the combined "some viewport of
        // ours is focused" signal to `false`, so
        // `update_viewer_keyboard_focus`'s own edge detector alone would
        // never fire -- yet a key held down against the previously active
        // viewport must never be carried forward as though still
        // depressed against the newly active one. Pointer lock must stay
        // untouched: an internal switch is not a real focus loss.
        let (mut app, mut receiver) = app_with_command_channel();
        let monitor_b = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_c = arcen_media::SessionMonitorId::new(3).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_b,
        )));
        seed_non_modifier_and_modifier(&mut app, &mut receiver);
        app.pointer_lock = true;

        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_c,
        )));

        assert_releases_before_reset(&mut receiver, "viewport_switch");
        assert!(receiver.try_recv().is_err());
        assert_eq!(app.keyboard.held_count(), 0);
        // The session as a whole is still legitimately keyboard-focused
        // (just on the newly active secondary), and pointer lock -- out of
        // this reason's scope -- is never touched by a pure switch.
        assert!(app.keyboard.focused());
        assert!(app.pointer_lock);
        assert_eq!(
            app.active_keyboard_viewport,
            Some(FocusedKeyboardViewport::Secondary(monitor_c))
        );
    }

    #[test]
    fn root_losing_focus_to_a_secondary_never_wrongly_latches_root_unfocused() {
        // The exact reviewer-reported bug this closes: root's own
        // per-frame OS focus flag going `true -> false` the instant a
        // secondary viewport of ours gains focus must never be treated as
        // a genuine focus-out (which would both release held keys with
        // the wrong reason and drop pointer lock) -- it is a viewport
        // switch, and the app as a whole is still frontmost.
        let (mut app, mut receiver) = app_with_command_channel();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Root));
        seed_non_modifier_and_modifier(&mut app, &mut receiver);
        app.pointer_lock = true;

        // Root's own OS focus flag would report `false` this frame (a
        // secondary now owns it), but the call site combines it with
        // `active_secondary_keyboard_focus` before ever reaching here --
        // simulated directly by passing the already-resolved combined
        // viewport.
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));

        assert_releases_before_reset(&mut receiver, "viewport_switch");
        assert_eq!(app.keyboard.held_count(), 0);
        assert!(app.keyboard.focused(), "root must not latch unfocused");
        assert!(
            app.pointer_lock,
            "a pure internal switch must never release pointer lock"
        );
    }

