    #[test]
    fn secondary_focused_root_focus_out_never_storms_key_releases() {
        // Regression: a Windows Pier two-display session. macOS focuses one
        // native window at a time, so while a secondary Arcen viewport owns
        // keyboard focus root's own `raw_input.focused` reads `false` on
        // *every* frame. The unguarded `self.keyboard.update_focus(false)`
        // here re-armed its own `true -> false` edge every frame (the same
        // frame's later `sync_keyboard_focus_across_viewports(Some(
        // Secondary(_)))` put it back to `true`), so a
        // `key_reset_modifiers` -- and a release of every held key -- was
        // emitted at the repaint rate for as long as the secondary stayed
        // focused: 7316 of them reached the host in one 6.4-minute session,
        // which is why held modifiers, chords, and key repeat all died.
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        app.active_secondary_keyboard_focus = Some(monitor_id);
        seed_non_modifier_and_modifier(&mut app, &mut receiver);

        let mut raw_input = egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        };
        for _ in 0..30 {
            eframe::App::raw_input_hook(&mut app, &egui::Context::default(), &mut raw_input);
            // Production frame shape: `drive_multi_window` re-resolves the
            // same still-focused secondary later in the very same frame.
            app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
                monitor_id,
            )));
        }

        assert!(
            receiver.try_recv().is_err(),
            "no key release or modifier reset may be emitted while one of our own secondary \
             viewports still owns keyboard focus",
        );
        assert!(
            app.keyboard.focused(),
            "the session as a whole is still keyboard-focused on the secondary viewport",
        );
        assert_eq!(
            app.keyboard.held_count(),
            2,
            "keys held against the focused secondary must survive root's per-frame focus-out",
        );
    }

    #[test]
    fn root_focus_out_after_a_secondary_loses_focus_still_releases_keys() {
        // The guard must only defer the release, never suppress it: once
        // the secondary genuinely gives up focus too, the total-focus-loss
        // edge resolved by `sync_keyboard_focus_across_viewports` must
        // still release every held key exactly once.
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        app.active_secondary_keyboard_focus = Some(monitor_id);
        seed_non_modifier_and_modifier(&mut app, &mut receiver);

        let mut raw_input = egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        };
        eframe::App::raw_input_hook(&mut app, &egui::Context::default(), &mut raw_input);
        assert!(receiver.try_recv().is_err());

        // Focus genuinely leaves the whole app: the secondary reports it is
        // no longer focused either.
        app.active_secondary_keyboard_focus = None;
        app.sync_keyboard_focus_across_viewports(None);

        assert_releases_before_reset(&mut receiver, "focus_out");
        assert_eq!(app.keyboard.held_count(), 0);
        assert!(!app.keyboard.focused());
    }

    #[test]
    fn root_focus_out_is_total_focus_loss_only_without_a_focused_secondary() {
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        assert!(root_focus_out_is_total_focus_loss(false, None));
        assert!(!root_focus_out_is_total_focus_loss(false, Some(monitor_id)));
        assert!(!root_focus_out_is_total_focus_loss(true, None));
        assert!(!root_focus_out_is_total_focus_loss(true, Some(monitor_id)));
    }

    /// Drains every currently queued session command and asserts none of
    /// them is a pointer-button or pen-event release -- tolerating (but
    /// not asserting on) any unrelated traffic, such as the keyboard's own
    /// existing (out of this fix's scope) `key_reset_modifiers` message.
    fn assert_no_pointer_or_pen_release_was_sent(
        receiver: &mut mpsc::UnboundedReceiver<SessionCommand>,
    ) {
        while let Ok(command) = receiver.try_recv() {
            if let SessionCommand::Json(value) = command {
                assert_ne!(
                    value["type"], "mouse_button",
                    "no pointer button release may be sent here, got: {value:?}"
                );
                assert_ne!(
                    value["type"], "pen_event",
                    "no pen release may be sent here, got: {value:?}"
                );
            }
        }
    }

    #[test]
    fn root_raw_input_hook_does_not_force_release_pointer_or_pen_while_a_secondary_is_focused() {
        // Item 1: `raw_input_hook` always runs *before* `logic()`/
        // `drive_multi_window` resolves this frame's secondary focus
        // sample, so it can never itself tell "focus moved to one of our
        // own secondaries" apart from "focus genuinely left the whole
        // app". It must no longer force a release directly here -- that
        // decision is deferred to `update_viewer_keyboard_focus`, driven by
        // the combined signal `sync_keyboard_focus_across_viewports`
        // computes once the secondary's own fresh sample is known.
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        app.pointer_lock = true;
        app.tablet_dispatcher
            .dispatch(vec![valid_pen_event(1, true, true)])
            .expect("no overflow");
        assert!(app.tablet_dispatcher.in_proximity());

        let mut raw_input = egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        };
        eframe::App::raw_input_hook(&mut app, &egui::Context::default(), &mut raw_input);

        assert!(
            app.pointer_lock,
            "raw_input_hook itself must never force-release pointer lock any more"
        );
        assert!(
            app.tablet_dispatcher.in_proximity(),
            "raw_input_hook itself must never force-release pen authority any more"
        );
        assert_no_pointer_or_pen_release_was_sent(&mut receiver);
    }

    #[test]
    fn secondary_focused_root_focus_out_leaves_pointer_and_pen_untouched_end_to_end() {
        // The full, production-shaped sequence within one tick:
        // `raw_input_hook` fires first (root's raw focus is false), then
        // `drive_multi_window`/`ui()` resolves this frame's secondary focus
        // and calls `sync_keyboard_focus_across_viewports` with the
        // combined signal -- which must still see the secondary as
        // focused and must not release anything either.
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Root));
        app.pointer_lock = true;
        app.tablet_dispatcher
            .dispatch(vec![valid_pen_event(1, true, true)])
            .expect("no overflow");

        let mut raw_input = egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        };
        eframe::App::raw_input_hook(&mut app, &egui::Context::default(), &mut raw_input);
        // This tick's later, authoritative resolution: the secondary took
        // over focus (not a genuine app-wide loss).
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));

        assert!(app.pointer_lock);
        assert!(app.tablet_dispatcher.in_proximity());
        assert_no_pointer_or_pen_release_was_sent(&mut receiver);
    }

    #[test]
    fn all_viewports_unfocused_releases_pointer_and_pen_exactly_once() {
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        app.pointer_lock = true;
        app.tablet_dispatcher
            .dispatch(vec![valid_pen_event(1, true, true)])
            .expect("no overflow");

        let mut raw_input = egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        };
        eframe::App::raw_input_hook(&mut app, &egui::Context::default(), &mut raw_input);
        // This tick's later resolution: nothing of ours is focused any
        // more -- focus genuinely left the whole app.
        app.sync_keyboard_focus_across_viewports(None);

        assert!(
            !app.pointer_lock,
            "a genuine total focus loss must release pointer lock"
        );
        assert!(
            !app.tablet_dispatcher.in_proximity(),
            "a genuine total focus loss must release pen authority"
        );
        // Drain whatever release traffic this genuine loss produced
        // (key_reset_modifiers at minimum) before proving idempotency.
        while receiver.try_recv().is_ok() {}

        // Idempotent: re-resolving the already-resolved "nothing focused"
        // state must not re-release / double-release.
        app.sync_keyboard_focus_across_viewports(None);
        assert!(!app.pointer_lock);
        assert!(!app.tablet_dispatcher.in_proximity());
        assert_no_pointer_or_pen_release_was_sent(&mut receiver);
    }

