    #[test]
    fn toggle_pointer_lock_lets_a_focused_secondary_acquire_and_release_its_own_lock() {
        // Enablement audit finding #2: ownership per viewport -- a
        // focused secondary can acquire its own relative pointer lock
        // through the exact same `TogglePointerLock` mechanism root uses,
        // never root's own `pointer_lock` bool.
        let (mut app, _receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        app.relative_pointer_confirmed = true;
        let monitor_id = arcen_media::SessionMonitorId::new(3).expect("valid id");
        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        let context = egui::Context::default();

        app.toggle_pointer_lock(&context);

        assert_eq!(app.secondary_pointer_lock, Some(monitor_id));
        assert!(
            !app.pointer_lock,
            "root's own lock must stay untouched by a secondary's own acquisition"
        );
        assert!(app.status.contains("secondary display"));

        app.toggle_pointer_lock(&context);

        assert!(
            app.secondary_pointer_lock.is_none(),
            "toggling again while this exact secondary owns the lock must release it"
        );
    }

