    #[test]
    fn pointer_lock_owner_switches_from_root_to_a_focused_secondary_and_back_without_auto_relock() {
        // Root <-> secondary owner switch: root's own lock releases the
        // instant a secondary is focused (existing, unchanged behavior),
        // that secondary can then acquire its own; when focus later
        // returns to root, the secondary's lock releases too, but root
        // never silently re-acquires on its own -- pointer lock, for
        // either owner, is and remains an explicit user toggle only.
        let (mut app, mut receiver) = app_with_command_channel();
        app.screen = AppScreen::InSession;
        app.relative_pointer_confirmed = true;
        let context = egui::Context::default();

        app.toggle_pointer_lock(&context);
        assert!(app.pointer_lock);
        assert!(app.secondary_pointer_lock.is_none());

        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.release_pointer_lock_if_secondary_focused(true);
        assert!(
            !app.pointer_lock,
            "root's stale lock must release the instant a secondary is focused"
        );
        while receiver.try_recv().is_ok() {}

        app.sync_keyboard_focus_across_viewports(Some(FocusedKeyboardViewport::Secondary(
            monitor_id,
        )));
        app.toggle_pointer_lock(&context);
        assert_eq!(app.secondary_pointer_lock, Some(monitor_id));
        while receiver.try_recv().is_ok() {}

        // Focus returns to root: the secondary's own lock must release.
        app.release_secondary_pointer_lock_if_not_focused(None);
        assert!(app.secondary_pointer_lock.is_none());
        assert!(
            !app.pointer_lock,
            "root must never silently re-acquire the lock on its own"
        );
    }

