    /// A held-button drag that leaves its origin monitor must resolve into
    /// the monitor that actually contains the cursor, not clamp to the
    /// origin's edge. The 2026-08-11 pier-windows.example.internal drag pressed at
    /// applied-desktop `(1089, 86)` and released at `(0, 1119)` -- exactly
    /// the primary's left edge -- because the position was clamped into the
    /// primary's own region and never crossed into the secondary.
    #[test]
    fn a_held_drag_leaving_the_primary_resolves_into_the_secondary_monitor() {
        use arcen_media::{MonitorDesktopRect, SessionMonitorId};

        // The exact applied geometry from that session.
        let roster = vec![
            (
                SessionMonitorId::new(1).expect("nonzero"),
                MonitorDesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3008,
                    height_px: 1692,
                },
            ),
            (
                SessionMonitorId::new(2).expect("nonzero"),
                MonitorDesktopRect {
                    x: -1800,
                    y: 0,
                    width_px: 1800,
                    height_px: 1130,
                },
            ),
        ];
        let primary = SessionMonitorId::new(1).expect("nonzero");

        // Dragging left past the primary's own origin: the unclamped
        // fraction goes negative, which is the crossing signal.
        let (monitor_id, fraction) =
            arcen_media::resolve_pointer_crossing(&roster, primary, (-0.2, 0.3))
                .expect("a drag past the left edge must resolve into the secondary");
        assert_eq!(monitor_id, SessionMonitorId::new(2).expect("nonzero"));
        assert!(
            fraction.0 > 0.0 && fraction.0 < 1.0,
            "the crossed position must land inside the secondary, got {fraction:?}",
        );

        // Still inside the primary: unchanged behaviour, no crossing.
        let (same, _) = arcen_media::resolve_pointer_crossing(&roster, primary, (0.5, 0.5))
            .expect("an in-bounds position still resolves");
        assert_eq!(same, primary);
    }

    /// A host that advertises `max_monitors: 1` rejects Match My Layout on
    /// every attempt, so the client must offer the one recovery inline
    /// instead of printing a message that points at a form the user is not
    /// in. The pier-windows-software.example.internal field report was exactly this: the error named
    /// a setting, and the tester could not reach it from where they were.
    ///
    /// The choice must be scoped to the failing connection, never applied
    /// app-wide -- one single-display host must not silently downgrade every
    /// other host.
    #[test]
    fn an_unsupported_multi_monitor_host_pins_single_display_to_that_connection_only() {
        let mut app = ArcenApp::default();
        let app_wide = app.displays_mode;

        let unsaved = ConnectionDraft::new(ConnectionKind::DirectMachine);
        app.apply_displays_unsupported_choice(&unsaved);

        assert_eq!(
            app.pending_displays_override,
            Some((connection_endpoint(&unsaved), DisplaysMode::SinglePrimary)),
            "the retry must actually stop requesting a layout the host cannot serve",
        );
        assert_eq!(
            app.displays_mode, app_wide,
            "one single-display host must not change the application-wide default",
        );
        assert!(
            !app.pending_desktop_replacement,
            "a capability mismatch is not a reason to destroy anyone's desktop",
        );
    }

    /// The 2026-08-12 evening report: after accepting a single display on
    /// pier-windows-software.example.internal, the *next* connection to pier-linux.example.internal came up on one
    /// screen too. `active_displays_mode` is the mode for the attempt about
    /// to start and nothing reset it between connections, so one host's
    /// choice silently followed the user to every host after it.
    ///
    /// The earlier test claimed to cover this but only asserted the
    /// application-wide default was untouched -- which it was. The leak was
    /// in the per-attempt field, so the assertion missed it entirely.
    #[test]
    fn a_single_display_choice_does_not_follow_the_user_to_the_next_host() {
        let mut app = ArcenApp::default();

        // Accept a single display for one host.
        let mut limited = ConnectionDraft::new(ConnectionKind::DirectMachine);
        limited.host = "single-display-host".to_string();
        app.apply_displays_unsupported_choice(&limited);
        // Its own retry consumes the one-shot and pins the attempt, exactly
        // as the successful pier-windows-software.example.internal reconnection did.
        app.active_displays_mode = app.resolve_attempt_displays_mode(&limited);
        assert_eq!(app.active_displays_mode, Some(DisplaysMode::SinglePrimary));

        // Now connect to a different, unsaved host that has expressed no
        // preference of its own.
        let mut other = ConnectionDraft::new(ConnectionKind::DirectMachine);
        other.host = "another-host".to_string();
        other.saved_connection_id = None;
        app.active_displays_mode = app.resolve_attempt_displays_mode(&other);

        assert_eq!(
            app.active_displays_mode, None,
            "a single-display host must not silently reduce the next host to one screen",
        );
        assert_eq!(
            app.pending_displays_override, None,
            "the one-shot must be consumed by the attempt it was meant for",
        );
    }

    /// The same one-shot must still reach the attempt it was created for,
    /// including when that connection is unsaved and so has nothing to read
    /// a preference back from.
    #[test]
    fn a_recovery_choice_reaches_the_retry_it_was_made_for() {
        let mut app = ArcenApp::default();

        let draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        app.apply_displays_unsupported_choice(&draft);
        app.active_displays_mode = app.resolve_attempt_displays_mode(&draft);

        assert_eq!(
            app.active_displays_mode,
            Some(DisplaysMode::SinglePrimary),
            "the retry must carry the choice the user just made",
        );
    }

    /// The pier-linux.example.internal field report: the host's topology-conflict close showed
    /// as raw red error text naming two options, with neither offered as a
    /// button. The reason arrives *wrapped* by the transport
    /// (`ClosedByHost` renders "host closed the connection during setup{0}"),
    /// so matching the reason exactly never fired. Build the message the way
    /// the transport actually builds it rather than asserting on a bare copy
    /// of the reason, which is precisely what hid this.
    #[test]
    fn a_topology_conflict_is_recognised_inside_the_transports_wrapped_close_message() {
        let wrapped = crate::transport::websocket::ConnectSmokeError::ClosedByHost(format!(
            ": {}",
            arcen_protocol::messages::MULTI_MONITOR_TOPOLOGY_CONFLICT_REASON
        ))
        .to_string();
        assert!(
            wrapped.starts_with("host closed the connection during setup"),
            "guard the assumption this test rests on: {wrapped}",
        );

        let mut app = ArcenApp::default();
        app.active_connection = Some(ConnectionDraft::new(ConnectionKind::DirectMachine));
        app.connection_generation = 3;
        let ctx = egui::Context::default();
        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::Protocol),
                message: wrapped,
                observed_at: Instant::now(),
            }),
            3,
            &ctx,
        );

        assert!(
            matches!(app.screen, AppScreen::TopologyConflict(_)),
            "naming both recoveries in red text while offering neither is the dead end \
             this screen exists to remove",
        );
    }

    /// Same wrapping hazard for the capability rejection.
    #[test]
    fn an_unsupported_multi_monitor_host_is_recognised_inside_a_wrapped_close_message() {
        let inner = crate::transport::websocket::ConnectSmokeError::MultiMonitorUnsupported(
            "requested topology has 2 monitors but max_monitors advertises 1".to_string(),
        )
        .to_string();
        let wrapped =
            crate::transport::websocket::ConnectSmokeError::ClosedByHost(format!(": {inner}"))
                .to_string();

        let mut app = ArcenApp::default();
        app.active_connection = Some(ConnectionDraft::new(ConnectionKind::DirectMachine));
        app.connection_generation = 4;
        let ctx = egui::Context::default();
        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::Protocol),
                message: wrapped,
                observed_at: Instant::now(),
            }),
            4,
            &ctx,
        );

        assert!(
            matches!(app.screen, AppScreen::DisplaysUnsupported(_)),
            "the single-display retry must survive transport wrapping too",
        );
    }

    #[test]
    fn an_unsupported_multi_monitor_host_is_offered_a_recovery_rather_than_a_dead_end() {
        // The failure arrives as an already-formatted transport message, so
        // the recognition path is prefix matching. Assert on the real
        // rendered error rather than a hand-written copy of it.
        let rendered = crate::transport::websocket::ConnectSmokeError::MultiMonitorUnsupported(
            "requested topology has 3 monitors but max_monitors advertises 2".to_string(),
        )
        .to_string();

        let mut app = ArcenApp::default();
        app.active_connection = Some(ConnectionDraft::new(ConnectionKind::DirectMachine));
        app.connection_generation = 7;
        let ctx = egui::Context::default();
        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::Protocol),
                message: rendered,
                observed_at: Instant::now(),
            }),
            7,
            &ctx,
        );

        assert!(
            matches!(app.screen, AppScreen::DisplaysUnsupported(_)),
            "the user must be offered Primary Display Only, not left on an error",
        );
        assert!(app.status.contains("requested topology has 3 monitors"));
        assert!(app.status.contains("max_monitors advertises 2"));
        assert!(!app.status.contains("supports one display"));
    }

    /// The host's topology-conflict close must become an explicit choice,
    /// never a dead-end error. Reconnecting falls back to the layout the
    /// existing desktop can actually serve; starting fresh carries the
    /// explicit replacement authorisation exactly once.
    #[test]
    fn a_topology_conflict_offers_both_recoveries_and_authorises_replacement_once() {
        let mut app = ArcenApp::default();

        // Choosing to keep the existing session must not authorise any
        // destructive replacement, and must stop asking for a layout the
        // desktop has already proven it cannot serve.
        app.apply_topology_conflict_choice("host:18444", false);
        assert!(!app.pending_desktop_replacement);
        assert_eq!(
            app.pending_displays_override,
            Some(("host:18444".to_string(), DisplaysMode::SinglePrimary)),
        );

        // Choosing to start fresh authorises the replacement and leaves the
        // requested layout alone.
        let mut app = ArcenApp::default();
        app.apply_topology_conflict_choice("host:18444", true);
        assert!(app.pending_desktop_replacement);
        assert_eq!(
            app.active_displays_mode, None,
            "starting fresh must keep asking for the layout the user actually wants",
        );

        // The authorisation is carried on the wire for that one attempt.
        let draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        let options = app.connect_options(&draft);
        assert!(options.replace_incompatible_desktop);

        // And an ordinary connect never carries it.
        let fresh = ArcenApp::default();
        assert!(!fresh.connect_options(&draft).replace_incompatible_desktop);
    }

    /// The refusal reason is one shared literal so the client can recognise
    /// this exact conflict; a drifting copy would silently turn the choice
    /// back into the dead end it replaced.
    #[test]
    fn the_topology_conflict_reason_is_recognisable_and_within_the_frame_budget() {
        let reason = arcen_protocol::messages::MULTI_MONITOR_TOPOLOGY_CONFLICT_REASON;
        assert!(
            reason.len() <= 120,
            "the close reason must fit the control-frame budget, got {} bytes",
            reason.len(),
        );
        assert!(
            !reason.to_ascii_lowercase().contains("sign out"),
            "the reason must not tell the user to recover by hand: {reason}",
        );
    }

    #[test]
    fn match_layout_gate_blocks_on_more_than_four_displays_when_the_runtime_is_available() {
        let result = match_layout_preflight(
            DisplaysMode::MatchLayout,
            5,
            Some(true),
            || Err(crate::display::topology::TopologyPreflightError::TooManyDisplays(5)),
            crate::protocol::messages::SafeAreaPolicyMsg::StandardFullscreen,
            false,
            true,
        );
        let message = result.expect_err(">4 displays must block Match My Layout");
        assert!(message.contains("Match My Layout cannot start"));
    }

    #[test]
    fn match_layout_gate_preserves_the_primary_only_fallback_on_more_than_four_displays_when_the_runtime_is_unavailable(
    ) {
        // Regression: >4 local displays must not block the connection while
        // the multi-window runtime is unavailable -- Deck was never going to
        // attach a real topology for them anyway
        // (`approved_multi_monitor_selection`), so it falls back to
        // primary-only exactly as it did before this tranche, and never
        // builds a topology at all.
        assert_eq!(
            match_layout_preflight(
                DisplaysMode::MatchLayout,
                5,
                Some(true),
                || panic!("must not build a topology while the runtime is unavailable"),
                crate::protocol::messages::SafeAreaPolicyMsg::StandardFullscreen,
                false,
                false,
            ),
            Ok(None)
        );
    }

    #[test]
    fn disclaimer_preserves_deferred_quick_connect_credentials() {
        let mut app = ArcenApp::default();
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "host.local".to_string();
        draft.username = "operator".to_string();
        app.pending_connection = Some(draft);
        app.deferred_auth = Some(AuthSubmission {
            username: "operator".to_string(),
            password: "dummy-password".to_string(),
        });
        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));

        app.handle_auth_request(AuthRequest {
            msg_type: crate::protocol::messages::AUTH_REQUEST.to_string(),
            auth_methods: vec!["pam".to_string()],
            challenge: String::new(),
            salt: String::new(),
            auth_mode: Some("pam".to_string()),
            disclaimer: Some("Authorized use only.".to_string()),
            multi_monitor_v1: None,
        });

        assert!(app
            .deferred_auth
            .as_ref()
            .is_some_and(|pending| pending.username == "operator"));
        assert!(app
            .deferred_auth
            .as_ref()
            .is_some_and(|pending| pending.password == "dummy-password"));
        assert!(app
            .pending_connection
            .as_ref()
            .is_some_and(|pending| pending.username.is_empty() && pending.password.is_empty()));
        assert!(matches!(app.screen, AppScreen::Disclaimer(_, _)));
        assert!(received.try_recv().is_err());
    }

    #[test]
    fn disclaimer_accept_submits_deferred_quick_connect_credentials() {
        let mut app = ArcenApp::default();
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "host.local".to_string();
        draft.username = "operator".to_string();
        app.pending_connection = Some(draft);
        app.deferred_auth = Some(AuthSubmission {
            username: "operator".to_string(),
            password: "dummy-password".to_string(),
        });
        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));

        app.handle_auth_request(AuthRequest {
            msg_type: crate::protocol::messages::AUTH_REQUEST.to_string(),
            auth_methods: vec!["password".to_string()],
            challenge: String::new(),
            salt: String::new(),
            auth_mode: Some("password".to_string()),
            disclaimer: Some("Authorized use only.".to_string()),
            multi_monitor_v1: None,
        });

        let AppScreen::Disclaimer(disclaimer_draft, _) = app.screen.clone() else {
            panic!("expected disclaimer screen");
        };
        if let Some(submission) = app.deferred_auth.take() {
            app.submit_auth_submission(disclaimer_draft, submission);
        } else {
            app.show_credentials(disclaimer_draft);
        }

        let SessionCommand::SubmitAuth(submission) = received.try_recv().unwrap() else {
            panic!("expected deferred auth submission after disclaimer accept");
        };
        assert_eq!(submission.username, "operator");
        assert_eq!(submission.password, "dummy-password");
        assert!(app.deferred_auth.is_none());
        assert!(matches!(app.screen, AppScreen::Connecting(_)));
    }

