    /// Builds a draft that clears every `start_connection` early-return gate
    /// deterministically (QUIC/TLS on a nonzero port), with
    /// `auto_reconnect` off so `configure_reconnect` stays a trivial no-op.
    fn deterministic_start_connection_draft() -> ConnectionDraft {
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "127.0.0.1".to_string();
        draft.username = "operator".to_string();
        draft.auto_reconnect = false;
        draft
    }

    #[tokio::test]
    async fn start_connection_installs_a_preloaded_submission_before_launch_so_an_immediate_auth_request_auto_submits(
    ) {
        // Saved-connection deferred-auth race fix, part 1: a submission
        // threaded through as `start_connection`'s own explicit
        // `preloaded_auth` argument (mirroring `HomeAction::Connect`'s own
        // preload-before-launch order) must be installed onto
        // `self.deferred_auth` no later than the moment the network launch
        // happens -- proven here by driving an `AuthRequest` immediately
        // afterward and confirming it auto-submits, never falling through to
        // the Credentials screen.
        let mut app = ArcenApp {
            displays_mode: DisplaysMode::SinglePrimary,
            ..ArcenApp::default()
        };
        let draft = deterministic_start_connection_draft();
        let preloaded_auth = Some(AuthSubmission {
            username: "operator".to_string(),
            password: "dummy-password".to_string(),
        });

        app.start_connection(draft, preloaded_auth, &egui::Context::default());

        assert!(
            matches!(app.screen, AppScreen::Connecting(_)),
            "a passing preflight must reach the network launch",
        );
        assert!(
            app.deferred_auth
                .as_ref()
                .is_some_and(|pending| pending.username == "operator"
                    && pending.password == "dummy-password"),
            "the preloaded submission must already be installed once the session is live",
        );

        // Swap in a test double for the auto-submit assertion below --
        // `start_connection` already installed the real spawned session's
        // command sender, which this test has no receiver for.
        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));

        app.handle_auth_request(AuthRequest {
            msg_type: crate::protocol::messages::AUTH_REQUEST.to_string(),
            auth_methods: vec!["password".to_string()],
            challenge: String::new(),
            salt: String::new(),
            auth_mode: Some("password".to_string()),
            disclaimer: None,
            multi_monitor_v1: None,
        });

        let SessionCommand::SubmitAuth(submission) = received.try_recv().unwrap() else {
            panic!("expected the preloaded submission to auto-submit immediately");
        };
        assert_eq!(submission.username, "operator");
        assert_eq!(submission.password, "dummy-password");
        assert!(app.deferred_auth.is_none());
        assert!(
            !matches!(app.screen, AppScreen::Credentials(_)),
            "a preloaded submission must never show the Credentials screen",
        );
    }

    #[tokio::test]
    async fn start_connection_without_a_preloaded_submission_still_shows_credentials() {
        // Saved-connection deferred-auth race fix, part 2: a caller with
        // nothing preloaded (`preloaded_auth: None`, exactly
        // `HomeAction::Connect`'s own no-password path) must keep
        // `deferred_auth` `None` all the way through the network launch, so
        // an immediate `AuthRequest` still falls through to the Credentials
        // screen exactly as before this fix.
        let mut app = ArcenApp {
            displays_mode: DisplaysMode::SinglePrimary,
            ..ArcenApp::default()
        };
        let draft = deterministic_start_connection_draft();

        app.start_connection(draft, None, &egui::Context::default());

        assert!(matches!(app.screen, AppScreen::Connecting(_)));
        assert!(
            app.deferred_auth.is_none(),
            "no submission was preloaded; it must stay None",
        );

        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));

        app.handle_auth_request(AuthRequest {
            msg_type: crate::protocol::messages::AUTH_REQUEST.to_string(),
            auth_methods: vec!["password".to_string()],
            challenge: String::new(),
            salt: String::new(),
            auth_mode: Some("password".to_string()),
            disclaimer: None,
            multi_monitor_v1: None,
        });

        assert!(matches!(app.screen, AppScreen::Credentials(_)));
        assert!(
            received.try_recv().is_err(),
            "nothing must auto-submit when no submission was ever preloaded",
        );
    }

    #[tokio::test]
    async fn start_connection_clears_an_obsolete_prior_deferred_auth_when_none_is_explicitly_preloaded(
    ) {
        // Saved-connection deferred-auth race fix, part 3: `start_connection`
        // must never read `self.deferred_auth` as an implicit input -- only
        // ever its own explicit `preloaded_auth` argument. A stale
        // `self.deferred_auth` left over from some earlier, unrelated
        // context (simulated here) must be cleared, never carried forward
        // into a fresh attempt that explicitly preloaded nothing.
        let mut app = ArcenApp {
            displays_mode: DisplaysMode::SinglePrimary,
            ..ArcenApp::default()
        };
        app.deferred_auth = Some(AuthSubmission {
            username: "obsolete-user".to_string(),
            password: "obsolete-password".to_string(),
        });
        let draft = deterministic_start_connection_draft();

        app.start_connection(draft, None, &egui::Context::default());

        assert!(
            app.deferred_auth.is_none(),
            "an obsolete prior submission must not leak into an attempt that explicitly \
             preloaded nothing",
        );

        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));

        app.handle_auth_request(AuthRequest {
            msg_type: crate::protocol::messages::AUTH_REQUEST.to_string(),
            auth_methods: vec!["password".to_string()],
            challenge: String::new(),
            salt: String::new(),
            auth_mode: Some("password".to_string()),
            disclaimer: None,
            multi_monitor_v1: None,
        });

        assert!(
            matches!(app.screen, AppScreen::Credentials(_)),
            "the obsolete submission must never auto-submit",
        );
        assert!(received.try_recv().is_err());
    }

    #[test]
    fn cancelling_credentials_closes_the_waiting_authentication() {
        let mut app = ArcenApp::default();
        let (commands, mut received) = mpsc::unbounded_channel();
        app.session_commands = Some(SessionCommandSender::for_test(commands));
        app.pending_connection = Some(ConnectionDraft::new(ConnectionKind::DirectMachine));

        app.cancel_credentials(ConnectionDraft::new(ConnectionKind::DirectMachine));

        let mut saw_close = false;
        while let Ok(command) = received.try_recv() {
            if matches!(command, SessionCommand::Close) {
                saw_close = true;
            }
        }
        assert!(saw_close);
        assert!(app.session_commands.is_none());
        assert!(app.pending_connection.is_none());
        assert!(matches!(app.screen, AppScreen::Home));
    }

