    #[test]
    fn quick_connect_trust_override_is_preserved() {
        let app = ArcenApp {
            security_mode: SecurityMode::Medium,
            performance_mode: PerformanceMode::Standard,
            displays_mode: DisplaysMode::Windowed,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "enterprise-host.local".to_string();
        draft.tls_trust = Some(TlsTrustConfig::private_ca("enterprise.pem".into()));

        let options = app.connect_options(&draft);
        assert!(matches!(
            &options.tls.mode,
            crate::transport::tls::TlsTrustMode::PrivateCa { ca_bundle }
                if ca_bundle == &std::path::PathBuf::from("enterprise.pem")
        ));
        // `performance_mode` here only pins `max_fps`; codec, chroma, bit
        // depth, range and matrix all come from `color_fidelity`, which is
        // still `ArcenApp::default()`'s Standard preset (`legacy_h264`).
        assert_eq!(options.profile.codec, "h264");
        assert_eq!(options.profile.chroma, "yuv420");
        assert_eq!(options.profile.bit_depth, "8");
        assert_eq!(options.profile.color_range, "limited");
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(options.profile.max_fps, 30);
        assert_eq!(options.displays_mode, "windowed");
    }

    #[test]
    fn effective_color_fidelity_variant_passes_through_a_coherent_resolution() {
        // Every preset alone is coherent (pinned by
        // `color_fidelity_preset_maps_to_documented_contract`), so the
        // effective variant is exactly the resolved one, unchanged.
        for preset in [
            ColorFidelity::Standard,
            ColorFidelity::FullColour,
            ColorFidelity::GradingReference,
        ] {
            let settings = ColorFidelitySettings {
                preset,
                overrides: ColorFidelityOverrides::default(),
                variant_override: None,
            };
            assert_eq!(
                effective_color_fidelity_variant(settings),
                settings.resolved_variant(),
                "{preset:?} is already coherent, so the effective variant must not change it"
            );
        }
    }

    #[test]
    fn effective_color_fidelity_variant_falls_back_to_the_preset_when_incoherent() {
        // Same incoherent combination as
        // `color_fidelity_axis_overrides_are_not_cross_validated_for_coherence`:
        // Standard's 4:2:0 chroma plus an identity-matrix override.
        let incoherent = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides {
                matrix: Some(arcen_media::ColorMatrix::Identity),
                ..ColorFidelityOverrides::default()
            },
            variant_override: None,
        };
        assert!(
            !incoherent.resolved_variant().is_coherent(),
            "test premise: this combination must actually be incoherent"
        );
        assert_eq!(
            effective_color_fidelity_variant(incoherent),
            arcen_media::video::VideoVariant::new(ColorFidelity::Standard.preset_configuration()),
            "an incoherent resolution must fall back to the preset's own contract, never reach \
             the host as-is"
        );
    }

    #[test]
    fn connect_options_thread_color_fidelity_axes_onto_the_wire_profile() {
        let draft = ConnectionDraft::new(ConnectionKind::DirectMachine);

        // Standard (the default) must produce exactly the wire values Arcen
        // shipped before colour fidelity existed, so a default user's
        // session is unchanged by this feature landing.
        let standard_app = ArcenApp {
            performance_mode: PerformanceMode::High,
            ..ArcenApp::default()
        };
        assert_eq!(
            standard_app.color_fidelity,
            ColorFidelitySettings::default()
        );
        let options = standard_app.connect_options(&draft);
        assert_eq!(options.profile.codec, "h264");
        assert_eq!(options.profile.chroma, "yuv420");
        assert_eq!(options.profile.bit_depth, "8");
        assert_eq!(options.profile.color_range, "limited");
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(options.profile.max_fps, 60);
        assert_eq!(
            options.profile.video_selection,
            arcen_protocol::messages::VideoSelectionIntent::AdaptivePerformance
        );

        // The Grading Reference preset threads its full contract through.
        let grading_app = ArcenApp {
            color_fidelity: ColorFidelitySettings {
                preset: ColorFidelity::GradingReference,
                overrides: ColorFidelityOverrides::default(),
                variant_override: None,
            },
            ..ArcenApp::default()
        };
        let options = grading_app.connect_options(&draft);
        assert_eq!(options.profile.codec, "h265");
        assert_eq!(options.profile.chroma, "yuv444");
        assert_eq!(options.profile.bit_depth, "10");
        assert_eq!(options.profile.color_range, "full");
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(
            options.profile.video_selection,
            arcen_protocol::messages::VideoSelectionIntent::ColorFidelity
        );

        // Persisted diagnostic overrides are accepted only by dev-tools
        // builds; production keeps the preset's compatibility contract.
        let override_app = ArcenApp {
            color_fidelity: ColorFidelitySettings {
                preset: ColorFidelity::Standard,
                overrides: ColorFidelityOverrides {
                    bit_depth: Some(arcen_media::BitDepth::Ten),
                    ..ColorFidelityOverrides::default()
                },
                variant_override: None,
            },
            ..ArcenApp::default()
        };
        let options = override_app.connect_options(&draft);
        assert_eq!(options.profile.codec, "h264");
        assert_eq!(options.profile.chroma, "yuv420");
        assert_eq!(
            options.profile.bit_depth,
            if cfg!(feature = "dev-tools") {
                "10"
            } else {
                "8"
            }
        );
        assert_eq!(options.profile.color_range, "limited");
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(
            options.profile.video_selection,
            arcen_protocol::messages::VideoSelectionIntent::AdaptivePerformance
        );

        // Explicit variants are likewise developer-only.
        let variant_app = ArcenApp {
            color_fidelity: ColorFidelitySettings {
                preset: ColorFidelity::Standard,
                overrides: ColorFidelityOverrides::default(),
                variant_override: Some(
                    arcen_media::video::VideoVariant::from_id("av1-444-12-full-bt709")
                        .expect("valid probe-matrix id"),
                ),
            },
            ..ArcenApp::default()
        };
        let options = variant_app.connect_options(&draft);
        assert_eq!(
            options.profile.codec,
            if cfg!(feature = "dev-tools") {
                "av1"
            } else {
                "h264"
            }
        );
        assert_eq!(
            options.profile.chroma,
            if cfg!(feature = "dev-tools") {
                "yuv444"
            } else {
                "yuv420"
            }
        );
        assert_eq!(
            options.profile.bit_depth,
            if cfg!(feature = "dev-tools") {
                "12"
            } else {
                "8"
            }
        );
        assert_eq!(
            options.profile.color_range,
            if cfg!(feature = "dev-tools") {
                "full"
            } else {
                "limited"
            }
        );
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(
            options.profile.video_selection,
            if cfg!(feature = "dev-tools") {
                arcen_protocol::messages::VideoSelectionIntent::Exact
            } else {
                arcen_protocol::messages::VideoSelectionIntent::AdaptivePerformance
            }
        );

        // An incoherent Advanced combination never reaches the wire: it
        // falls back to the preset's own contract instead.
        let incoherent_app = ArcenApp {
            color_fidelity: ColorFidelitySettings {
                preset: ColorFidelity::Standard,
                overrides: ColorFidelityOverrides {
                    matrix: Some(arcen_media::ColorMatrix::Identity),
                    ..ColorFidelityOverrides::default()
                },
                variant_override: None,
            },
            ..ArcenApp::default()
        };
        let options = incoherent_app.connect_options(&draft);
        assert_eq!(
            options.profile.codec, "h264",
            "an incoherent combination must fall back to the Standard preset, never reach the \
             wire as an unsupported combination"
        );
        assert_eq!(options.profile.chroma, "yuv420");
        assert_eq!(options.profile.bit_depth, "8");
        assert_eq!(options.profile.color_range, "limited");
        assert_eq!(options.profile.color_matrix, "bt709");
        assert_eq!(
            options.profile.video_selection,
            arcen_protocol::messages::VideoSelectionIntent::AdaptivePerformance
        );
    }

    #[test]
    fn connect_options_thread_encode_intent_onto_the_wire_profile() {
        let draft = ConnectionDraft::new(ConnectionKind::DirectMachine);

        let default_app = ArcenApp::default();
        assert_eq!(
            default_app.encode_intent,
            arcen_media::EncodeIntent::Interactive
        );
        let options = default_app.connect_options(&draft);
        assert_eq!(
            options.profile.encode_intent, "interactive",
            "an untouched install must keep asking for the latency-first encode Arcen has \
             always used",
        );

        // Grading Reference owns the image-quality/latency trade; users do not
        // select a separate encoder intent.
        let grading_app = ArcenApp {
            color_fidelity: ColorFidelitySettings {
                preset: ColorFidelity::GradingReference,
                overrides: ColorFidelityOverrides::default(),
                variant_override: None,
            },
            ..ArcenApp::default()
        };
        assert_eq!(
            grading_app.connect_options(&draft).profile.encode_intent,
            "quality",
            "Grading Reference must automatically request the quality encoder intent",
        );

        // A legacy persisted independent intent is ignored.
        let quality_app = ArcenApp {
            encode_intent: arcen_media::EncodeIntent::Quality,
            ..ArcenApp::default()
        };
        let options = quality_app.connect_options(&draft);
        assert_eq!(options.profile.encode_intent, "interactive");
        assert_eq!(options.profile.codec, "h264");
        assert_eq!(options.profile.chroma, "yuv420");
        assert_eq!(options.profile.bit_depth, "8");
        assert_eq!(options.profile.color_range, "limited");
        assert_eq!(options.profile.color_matrix, "bt709");
    }

    #[test]
    fn actual_certificate_event_opens_warning_without_storing_trust() {
        let mut app = ArcenApp {
            security_mode: SecurityMode::Medium,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "tofu-host.local".to_string();
        app.pending_connection = Some(draft);

        app.handle_certificate_untrusted(test_cert_info());

        assert!(app.accepted_tls_pins.lock().unwrap().is_empty());
        assert!(matches!(app.screen, AppScreen::CertificateWarning(_, _)));
    }

    #[test]
    fn certificate_warning_preserves_deferred_quick_connect_credentials() {
        let mut app = ArcenApp::default();
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "tofu-host.local".to_string();
        draft.username = "operator".to_string();
        app.pending_connection = Some(draft);
        app.deferred_auth = Some(AuthSubmission {
            username: "operator".to_string(),
            password: "dummy-password".to_string(),
        });

        app.handle_certificate_untrusted(test_cert_info());

        assert!(matches!(app.screen, AppScreen::CertificateWarning(_, _)));
        assert!(app
            .deferred_auth
            .as_ref()
            .is_some_and(|submission| submission.username == "operator"));
        assert!(app
            .deferred_auth
            .as_ref()
            .is_some_and(|submission| submission.password == "dummy-password"));
    }

    #[test]
    fn trust_stores_spki_and_retry_uses_typed_spki_pin() {
        let app = ArcenApp {
            security_mode: SecurityMode::Medium,
            ..ArcenApp::default()
        };
        let info = test_cert_info();
        let mut accepted = ConnectionDraft::new(ConnectionKind::DirectMachine);
        accepted.host = "tofu-host.local".to_string();
        app.trust_certificate_for_session(&accepted, &info);

        assert_eq!(
            app.accepted_tls_pins
                .lock()
                .unwrap()
                .get(&connection_endpoint(&accepted)),
            Some(&info.spki_sha256)
        );
        assert!(matches!(
            app.connect_options(&accepted).tls.mode,
            crate::transport::tls::TlsTrustMode::TofuPinned { pin }
                if pin == info.spki_sha256
        ));
    }

    #[test]
    fn untrusted_medium_endpoint_uses_capture_probe() {
        let app = ArcenApp {
            security_mode: SecurityMode::Medium,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "public-ca-host.local".to_string();

        assert!(matches!(
            app.connect_options(&draft).tls.mode,
            crate::transport::tls::TlsTrustMode::TofuPending
        ));
    }

    #[test]
    fn high_security_ignores_process_tofu_trust() {
        let app = ArcenApp {
            security_mode: SecurityMode::High,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "previously-trusted.local".to_string();
        app.accepted_tls_pins.lock().unwrap().insert(
            connection_endpoint(&draft),
            arcen_transport::tls::TlsPin::new(
                arcen_transport::tls::PinKind::SubjectPublicKeyInfoSha256,
                [0x42; 32],
            ),
        );

        assert!(matches!(
            app.connect_options(&draft).tls.mode,
            crate::transport::tls::TlsTrustMode::SystemCa
        ));
    }

    #[test]
    fn low_security_uses_tls_double_gate_without_warning() {
        let app = ArcenApp {
            security_mode: SecurityMode::Low,
            ..ArcenApp::default()
        };
        let draft = ConnectionDraft::new(ConnectionKind::DirectMachine);

        let options = app.connect_options(&draft);
        assert!(matches!(
            options.tls.mode,
            crate::transport::tls::TlsTrustMode::InsecureSkipVerify
        ));
        assert!(options.tls.insecure_cli_flag);
    }

