    #[test]
    fn client_settings_round_trip_via_config_dir() {
        let _guard = CONFIG_ENV_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let dir = std::env::current_dir()
            .unwrap()
            .join("target")
            .join(format!("arcen-settings-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let repository = ClientConfigRepository::at(dir.clone());

        // With no file present, defaults are conservative and portable.
        let defaults = load_client_settings(&repository).unwrap();
        assert_eq!(
            defaults.log_level,
            if cfg!(debug_assertions) {
                LogLevel::Info
            } else {
                LogLevel::Critical
            }
        );
        assert_eq!(defaults.security_mode, SecurityMode::Medium);
        assert_eq!(defaults.performance_mode, PerformanceMode::Standard);
        assert_eq!(defaults.displays_mode, DisplaysMode::MatchLayout);
        assert_eq!(defaults.cursor_preference, CursorMode::Local);
        assert!(defaults.clipboard_enabled);
        assert!(defaults.tablet_input_enabled);
        assert_eq!(
            defaults.color_fidelity,
            ColorFidelitySettings::default(),
            "a settings.json predating color fidelity must resolve to the Standard preset \
             with no overrides",
        );
        assert_eq!(
            defaults.encode_intent,
            arcen_media::EncodeIntent::Interactive,
            "a settings.json predating encode intent must stay latency-first",
        );

        save_client_settings(
            &repository,
            &ClientSettings {
                log_level: LogLevel::Debug,
                security_mode: SecurityMode::Low,
                performance_mode: PerformanceMode::Standard,
                displays_mode: DisplaysMode::Windowed,
                cursor_preference: CursorMode::Host,
                clipboard_enabled: false,
                microphone_enabled: true,
                hidpi_streaming: true,
                fullscreen_uses_notch_area: true,
                remote_ui_scale_percent: 150,
                full_color_display_mask: 0b0001,
                hidpi_display_mask: 0b0010,
                tablet_input_enabled: false,
                tablet_mode_requested: TabletModeMsg::DisabledMouseCompat,
                color_fidelity: ColorFidelitySettings {
                    preset: ColorFidelity::GradingReference,
                    overrides: ColorFidelityOverrides {
                        codec: Some(arcen_media::VideoCodec::Av1),
                        chroma: Some(arcen_media::ChromaSubsampling::Yuv422),
                        bit_depth: Some(arcen_media::BitDepth::Twelve),
                        range: Some(arcen_media::ColorRange::Limited),
                        matrix: Some(arcen_media::ColorMatrix::Identity),
                    },
                    variant_override: Some(
                        arcen_media::video::VideoVariant::from_id("av1-444-12-full-bt709")
                            .expect("valid probe-matrix id"),
                    ),
                },
                encode_intent: arcen_media::EncodeIntent::Quality,
            },
        )
        .unwrap();
        let loaded = load_client_settings(&repository).unwrap();
        assert_eq!(loaded.log_level, LogLevel::Debug);
        assert_eq!(loaded.security_mode, SecurityMode::Low);
        assert_eq!(loaded.performance_mode, PerformanceMode::Standard);
        assert_eq!(loaded.displays_mode, DisplaysMode::Windowed);
        assert_eq!(loaded.cursor_preference, CursorMode::Host);
        assert!(!loaded.clipboard_enabled);
        assert!(!loaded.microphone_enabled);
        assert!(loaded.hidpi_streaming);
        assert!(
            loaded.fullscreen_uses_notch_area,
            "the notch-area opt-in must round-trip through settings.json"
        );
        assert_eq!(
            loaded.remote_ui_scale_percent, 150,
            "the remote UI scale must round-trip through settings.json"
        );
        assert!(!loaded.tablet_input_enabled);
        assert_eq!(
            loaded.tablet_mode_requested,
            TabletModeMsg::DisabledMouseCompat
        );
        assert_eq!(
            loaded.color_fidelity,
            ColorFidelitySettings {
                preset: ColorFidelity::GradingReference,
                overrides: ColorFidelityOverrides {
                    codec: Some(arcen_media::VideoCodec::Av1),
                    chroma: Some(arcen_media::ChromaSubsampling::Yuv422),
                    bit_depth: Some(arcen_media::BitDepth::Twelve),
                    range: Some(arcen_media::ColorRange::Limited),
                    matrix: Some(arcen_media::ColorMatrix::Identity),
                },
                variant_override: Some(
                    arcen_media::video::VideoVariant::from_id("av1-444-12-full-bt709")
                        .expect("valid probe-matrix id"),
                ),
            },
            "color fidelity preset, every advanced override, and the explicit variant \
             override must all round-trip through settings.json",
        );
        assert_eq!(
            loaded.encode_intent,
            arcen_media::EncodeIntent::Quality,
            "the encode intent must round-trip through settings.json",
        );
        let saved: serde_json::Value =
            serde_json::from_slice(&std::fs::read(dir.join("settings.json")).unwrap()).unwrap();
        assert!(saved.get("microphone_enabled").is_none());
        assert_eq!(
            saved.get("encode_intent"),
            Some(&serde_json::Value::from("quality")),
            "intent is persisted as its wire token, so settings.json and the quality_settings \
             message can never drift apart",
        );

        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn gui_default_and_settings_save_keep_process_proof_recurring() {
        let _guard = CONFIG_ENV_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let root = std::env::current_dir()
            .unwrap()
            .join("target")
            .join(format!("arcen-proof-regression-{}", std::process::id()));
        let config = root.join("config");
        let logs = root.join("logs");
        let _ = std::fs::remove_dir_all(&root);
        std::env::set_var("ARCEN_LOG_DIR", &logs);

        crate::logging::init(crate::logging::default_profile()).expect("Deck logging initializes");
        let first = crate::logging::trigger_proof_for_test().expect("initial process proof");
        let app = ArcenApp::from_config_repository(ClientConfigRepository::at(config.clone()));
        let second = crate::logging::trigger_proof_for_test().expect("proof after GUI default");
        assert!(second > first);
        app.persist_settings().expect("settings save");
        let third = crate::logging::trigger_proof_for_test().expect("proof after settings save");
        assert!(third > second);

        crate::logging::shutdown();
        std::env::remove_var("ARCEN_LOG_DIR");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn legacy_settings_json_without_tablet_input_enabled_defaults_true_and_preserves_unknown_fields(
    ) {
        let _guard = CONFIG_ENV_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let dir = std::env::current_dir()
            .unwrap()
            .join("target")
            .join(format!(
                "arcen-settings-tablet-migration-{}",
                std::process::id()
            ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        // A legacy settings file predating the `tablet_input_enabled` key,
        // plus an unrelated future field this version doesn't know about.
        std::fs::write(
            dir.join("settings.json"),
            r#"{"clipboard_enabled":false,"a_future_field_this_version_does_not_know":42}"#,
        )
        .unwrap();
        let repository = ClientConfigRepository::at(dir.clone());

        let loaded = load_client_settings(&repository).unwrap();
        assert!(
            loaded.tablet_input_enabled,
            "missing key must migrate to the safe default (true), not false"
        );
        assert!(!loaded.clipboard_enabled);

        // Saving must not clobber the unknown future field: settings
        // persistence merges into the existing JSON object rather than
        // overwriting it wholesale.
        save_client_settings(&repository, &loaded).unwrap();
        let saved: serde_json::Value =
            serde_json::from_slice(&std::fs::read(dir.join("settings.json")).unwrap()).unwrap();
        assert_eq!(
            saved.get("a_future_field_this_version_does_not_know"),
            Some(&serde_json::Value::from(42))
        );
        assert_eq!(
            saved.get("tablet_input_enabled"),
            Some(&serde_json::Value::Bool(true))
        );

        let _ = std::fs::remove_dir_all(dir);
    }

