    #[test]
    fn submitted_saved_username_survives_host_failure_and_connection_switches() {
        let _guard = CONFIG_ENV_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let dir = test_config_dir("arcen-submitted-username-failure");
        let _ = std::fs::remove_dir_all(&dir);
        let repository = ClientConfigRepository::at(dir.clone());
        let (commands, mut received) = mpsc::unbounded_channel();
        let mut app = ArcenApp {
            config_repository: repository.clone(),
            saved_connections: vec![
                saved_connection(
                    "co",
                    "pier-windows-software.example.internal",
                    "pier-windows-software.example.internal",
                    18443,
                    Some("admin"),
                ),
                saved_connection(
                    "resolve",
                    "pier-windows.example.internal",
                    "pier-windows.example.internal",
                    18443,
                    Some("admin"),
                ),
            ],
            session_commands: Some(SessionCommandSender::for_test(commands)),
            ..ArcenApp::default()
        };
        app.persist_saved_connections().unwrap();
        let mut co = ConnectionDraft::new(ConnectionKind::DirectMachine);
        co.saved_connection_id = Some("co".to_string());
        co.host = "pier-windows-software.example.internal".to_string();
        co.username = r"AD\artist.user".to_string();
        co.password = "not-persisted".to_string();

        app.submit_credentials(co);

        let SessionCommand::SubmitAuth(submission) = received.try_recv().unwrap() else {
            panic!("expected submitted credentials");
        };
        assert_eq!(submission.username, r"AD\artist.user");
        let persisted = load_saved_connections(&repository).unwrap().unwrap();
        assert_eq!(
            persisted.connections[0]
                .settings
                .remembered_username
                .as_deref(),
            Some(r"AD\artist.user")
        );
        assert_eq!(
            persisted.connections[1]
                .settings
                .remembered_username
                .as_deref(),
            Some("admin")
        );

        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::Protocol),
                message: "console/display setup failed after authentication".to_string(),
                observed_at: Instant::now(),
            }),
            app.connection_generation,
            &egui::Context::default(),
        );
        let mut resolve = ConnectionDraft::new(ConnectionKind::DirectMachine);
        resolve.saved_connection_id = Some("resolve".to_string());
        app.load_saved_username(&mut resolve);
        let mut co_again = ConnectionDraft::new(ConnectionKind::DirectMachine);
        co_again.saved_connection_id = Some("co".to_string());
        app.load_saved_username(&mut co_again);

        assert_eq!(resolve.username, "admin");
        assert_eq!(co_again.username, r"AD\artist.user");
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn invalid_submitted_usernames_never_replace_a_saved_username() {
        assert!(validated_remembered_username("").is_none());
        assert!(validated_remembered_username("artist\nadmin").is_none());
        assert!(validated_remembered_username(&"a".repeat(256)).is_none());
        assert_eq!(
            validated_remembered_username(&"a".repeat(255))
                .as_deref()
                .map(str::len),
            Some(255)
        );

        let mut app = ArcenApp {
            saved_connections: vec![saved_connection(
                "saved",
                "Saved",
                "saved",
                18443,
                Some("previous"),
            )],
            ..ArcenApp::default()
        };
        for invalid in ["", "artist\nadmin"] {
            app.remember_username_for_connection("saved", invalid);
        }
        app.remember_username_for_connection("saved", &"a".repeat(256));
        assert_eq!(
            app.saved_connections[0]
                .settings
                .remembered_username
                .as_deref(),
            Some("previous")
        );
    }

