    #[test]
    fn atomic_write_failure_and_panic_leave_previous_json_intact() {
        let dir = test_config_dir("arcen-atomic-write-failure");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("connections.json");
        let original = br#"{"version":2,"connections":[]}"#;
        atomic_write_json(&path, original).unwrap();

        let error = atomic_write_json_with_hook(&path, br#"{"broken":true}"#, |step| {
            if matches!(step, AtomicWriteStep::Synced) {
                return Err(std::io::Error::other("injected pre-rename failure"));
            }
            Ok(())
        });
        assert!(matches!(error, Err(ClientConfigError::Io(_))));
        assert_eq!(std::fs::read(&path).unwrap(), original);

        let panic_result = std::panic::catch_unwind(|| {
            let _ = atomic_write_json_with_hook(&path, br#"{"broken":true}"#, |step| {
                if matches!(step, AtomicWriteStep::Created) {
                    panic!("injected atomic-write panic");
                }
                Ok(())
            });
        });
        assert!(panic_result.is_err());
        assert_eq!(std::fs::read(&path).unwrap(), original);
        assert!(std::fs::read_dir(&dir).unwrap().all(|entry| {
            !entry
                .unwrap()
                .file_name()
                .to_string_lossy()
                .contains(".tmp-")
        }));
        let _ = std::fs::remove_dir_all(dir);
    }

