    #[test]
    fn fresh_selection_and_username_mutations_preserve_other_process_changes() {
        let dir = test_config_dir("arcen-fresh-mutations");
        let _ = std::fs::remove_dir_all(&dir);
        let repository_a = ClientConfigRepository::at(dir.clone());
        let repository_b = repository_a.clone();
        save_saved_connections(
            &repository_a,
            &SavedConnectionsStore::with_connections(vec![saved_connection(
                "one",
                "One",
                "one",
                18443,
                Some("one-old"),
            )]),
        );
        let stale_a = load_saved_connections(&repository_a).unwrap().unwrap();

        repository_b
            .add_connection(saved_connection(
                "two",
                "Two",
                "two",
                19443,
                Some("two-old"),
            ))
            .unwrap();
        repository_a.set_last_selected("one").unwrap();
        repository_b
            .set_remembered_username("two", Some("two-new".to_string()))
            .unwrap();
        repository_a
            .set_remembered_username("one", Some("one-new".to_string()))
            .unwrap();

        let converged = load_saved_connections(&repository_a).unwrap().unwrap();
        assert_eq!(converged.connections.len(), 2);
        assert_eq!(
            converged.last_selected_connection_id.as_deref(),
            Some("one")
        );
        assert_eq!(
            converged.connections[0]
                .settings
                .remembered_username
                .as_deref(),
            Some("one-new")
        );
        assert_eq!(
            converged.connections[1]
                .settings
                .remembered_username
                .as_deref(),
            Some("two-new")
        );
        assert!(matches!(
            repository_a.save_connections_snapshot(&stale_a),
            Err(ClientConfigError::StaleSnapshot)
        ));
        assert_eq!(
            load_saved_connections(&repository_a)
                .unwrap()
                .unwrap()
                .connections
                .len(),
            2
        );
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn stale_edit_and_delete_report_conflicts_without_data_loss() {
        let dir = test_config_dir("arcen-edit-delete-conflicts");
        let _ = std::fs::remove_dir_all(&dir);
        let repository_a = ClientConfigRepository::at(dir.clone());
        let repository_b = repository_a.clone();
        let original = saved_connection("one", "Original", "one", 18443, Some("artist"));
        save_saved_connections(
            &repository_a,
            &SavedConnectionsStore::with_connections(vec![original.clone()]),
        );
        let mut changed = original.clone();
        changed.name = "Changed by B".to_string();
        repository_b
            .update_connection("one", &original, changed.clone())
            .unwrap();

        let mut stale_update = original.clone();
        stale_update.host = "stale".to_string();
        assert!(matches!(
            repository_a.update_connection("one", &original, stale_update),
            Err(ClientConfigError::ConnectionChanged(id)) if id == "one"
        ));
        assert!(matches!(
            repository_a.delete_connection("one", &original),
            Err(ClientConfigError::ConnectionChanged(id)) if id == "one"
        ));
        assert_eq!(
            load_saved_connections(&repository_a)
                .unwrap()
                .unwrap()
                .connections[0]
                .name,
            "Changed by B"
        );
        repository_a.delete_connection("one", &changed).unwrap();
        assert!(load_saved_connections(&repository_a)
            .unwrap()
            .unwrap()
            .connections
            .is_empty());
        let _ = std::fs::remove_dir_all(dir);
    }

