    #[test]
    fn busy_connection_lock_returns_bounded_error_without_changing_json() {
        let dir = test_config_dir("arcen-lock-busy");
        let _ = std::fs::remove_dir_all(&dir);
        let repository = ClientConfigRepository::at(dir.clone());
        save_saved_connections(
            &repository,
            &SavedConnectionsStore::with_connections(vec![saved_connection(
                "one",
                "One",
                "one",
                18443,
                Some("original"),
            )]),
        );
        let path = dir.join("connections.json");
        let original = std::fs::read(&path).unwrap();
        let holder = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(repository.connections_lock_file().unwrap())
            .unwrap();
        holder.lock().unwrap();

        let started = Instant::now();
        let result = repository.set_remembered_username("one", Some("must-not-save".to_string()));
        let elapsed = started.elapsed();
        assert!(matches!(result, Err(ClientConfigError::ConfigBusy)));
        assert!(
            elapsed < Duration::from_millis(500),
            "busy config lock took {elapsed:?}"
        );
        assert_eq!(
            ClientConfigError::ConfigBusy.to_string(),
            "another Deck instance is updating saved connections; try again"
        );
        assert_eq!(std::fs::read(&path).unwrap(), original);

        drop(holder);
        repository
            .set_remembered_username("one", Some("saved-after-release".to_string()))
            .unwrap();
        assert_eq!(
            load_saved_connections(&repository)
                .unwrap()
                .unwrap()
                .connections[0]
                .settings
                .remembered_username
                .as_deref(),
            Some("saved-after-release")
        );
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn independent_repositories_converge_under_parallel_mutations() {
        let dir = test_config_dir("arcen-parallel-repositories");
        let _ = std::fs::remove_dir_all(&dir);
        let repository = ClientConfigRepository::at(dir.clone());
        save_saved_connections(
            &repository,
            &SavedConnectionsStore::with_connections(vec![saved_connection(
                "one", "One", "one", 18443, None,
            )]),
        );
        let repository_a = repository.clone();
        let repository_b = repository.clone();
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(3));
        let barrier_a = barrier.clone();
        let a = std::thread::spawn(move || {
            barrier_a.wait();
            repository_a.add_connection(saved_connection("two", "Two", "two", 19443, Some("admin")))
        });
        let barrier_b = barrier.clone();
        let b = std::thread::spawn(move || {
            barrier_b.wait();
            repository_b.set_remembered_username("one", Some("artist".to_string()))
        });
        barrier.wait();
        match a.join().unwrap() {
            Ok(_) => {}
            Err(ClientConfigError::ConfigBusy) => {
                repository
                    .add_connection(saved_connection("two", "Two", "two", 19443, Some("admin")))
                    .unwrap();
            }
            Err(error) => panic!("unexpected add failure: {error}"),
        }
        match b.join().unwrap() {
            Ok(_) => {}
            Err(ClientConfigError::ConfigBusy) => {
                repository
                    .set_remembered_username("one", Some("artist".to_string()))
                    .unwrap();
            }
            Err(error) => panic!("unexpected username failure: {error}"),
        }

        let converged = load_saved_connections(&repository).unwrap().unwrap();
        assert_eq!(converged.connections.len(), 2);
        assert_eq!(
            converged.connections[0]
                .settings
                .remembered_username
                .as_deref(),
            Some("artist")
        );
        let _ = std::fs::remove_dir_all(dir);
    }

