    #[test]
    fn performance_mode_maps_to_frame_rate_ceiling() {
        assert_eq!(PerformanceMode::Standard.max_fps(), 30);
        assert_eq!(PerformanceMode::High.max_fps(), 60);
        assert_eq!(PerformanceMode::HighLegacy.max_fps(), 60);
    }

    #[test]
    fn performance_mode_no_longer_carries_codec_or_chroma() {
        // `PerformanceMode` used to also pick codec/chroma (High = HEVC
        // 4:4:4, the other two modes = H.264 4:2:0); that is now entirely
        // `ColorFidelity`'s job, so `High` and `HighLegacy` are deliberately
        // behaviourally identical -- both are just the 60 fps ceiling. This
        // test exists so that fact is a pinned, intentional property rather
        // than something a future change silently reintroduces a codec/chroma
        // split for.
        assert_eq!(
            PerformanceMode::High.max_fps(),
            PerformanceMode::HighLegacy.max_fps()
        );
    }

    #[test]
    fn settings_enum_keys_round_trip() {
        for mode in [SecurityMode::High, SecurityMode::Medium, SecurityMode::Low] {
            assert_eq!(SecurityMode::from_key(mode.key()), mode);
        }
        for mode in [
            PerformanceMode::Standard,
            PerformanceMode::High,
            PerformanceMode::HighLegacy,
        ] {
            assert_eq!(PerformanceMode::from_key(mode.key()), mode);
        }
        for preset in [
            ColorFidelity::Standard,
            ColorFidelity::FullColour,
            ColorFidelity::GradingReference,
        ] {
            assert_eq!(ColorFidelity::from_key(preset.key()), preset);
        }
        for level in LogLevel::ALL {
            assert_eq!(LogLevel::from_index(level.index()), level);
        }
        assert_eq!(
            LogLevel::ALL.map(LogLevel::label),
            [
                "Level 0 Critical",
                "Level 1 Error",
                "Level 2 Info",
                "Level 3 Debug",
            ]
        );
        assert_eq!(
            LogLevel::ALL.map(LogLevel::profile),
            [
                arcen_telemetry::OperationalProfile::Critical,
                arcen_telemetry::OperationalProfile::Error,
                arcen_telemetry::OperationalProfile::Info,
                arcen_telemetry::OperationalProfile::Debug,
            ]
        );
    }

    #[test]
    fn color_fidelity_preset_maps_to_documented_contract() {
        // Standard = H.264 4:2:0 8-bit limited (Arcen's historical contract);
        // Full Colour = HEVC 4:4:4 8-bit full range; Grading Reference = HEVC
        // 4:4:4 10-bit full range BT.709. These are exactly the contracts the
        // Advanced settings UI promises by name, so they must match precisely
        // rather than merely "close enough".
        assert_eq!(
            ColorFidelity::Standard.preset_configuration(),
            arcen_media::VideoConfiguration::legacy_h264()
        );
        assert_eq!(
            ColorFidelity::FullColour.preset_configuration(),
            arcen_media::VideoConfiguration {
                codec: arcen_media::VideoCodec::H265,
                chroma: arcen_media::ChromaSubsampling::Yuv444,
                bit_depth: arcen_media::BitDepth::Eight,
                range: arcen_media::ColorRange::Full,
                matrix: arcen_media::ColorMatrix::Bt709,
                primaries: arcen_media::ColorPrimaries::Bt709,
                transfer: arcen_media::TransferCharacteristics::Bt709,
            }
        );
        assert_eq!(
            ColorFidelity::GradingReference.preset_configuration(),
            arcen_media::VideoConfiguration::grading_reference()
        );
        assert_eq!(
            ColorFidelity::Standard.describe(),
            "Automatic performance codec, 4:2:0 8-bit limited range"
        );
        assert_eq!(
            ColorFidelity::FullColour.describe(),
            "4:4:4 8-bit full range -- no chroma subsampling"
        );
        assert_eq!(
            ColorFidelity::GradingReference.describe(),
            "4:4:4 10-bit full range BT.709 -- best image quality, with added latency"
        );
        // Every preset, taken alone with no overrides and no explicit
        // variant, must resolve to a coherent, offered variant.
        for preset in [
            ColorFidelity::Standard,
            ColorFidelity::FullColour,
            ColorFidelity::GradingReference,
        ] {
            let settings = ColorFidelitySettings {
                preset,
                overrides: ColorFidelityOverrides::default(),
                variant_override: None,
            };
            assert!(
                settings.resolved_variant().is_coherent(),
                "{preset:?} must resolve to a coherent, offered variant"
            );
        }
    }

