    #[test]
    fn color_fidelity_resolution_precedence() {
        // No overrides, no explicit variant: the preset's own contract wins.
        let preset_only = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides::default(),
            variant_override: None,
        };
        assert_eq!(
            preset_only.resolved_variant(),
            arcen_media::video::VideoVariant::new(arcen_media::VideoConfiguration::legacy_h264())
        );

        // A single overridden axis replaces just that axis; every other axis
        // still comes from the preset.
        let one_override = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides {
                bit_depth: Some(arcen_media::BitDepth::Ten),
                ..ColorFidelityOverrides::default()
            },
            variant_override: None,
        };
        assert_eq!(
            one_override.resolved_variant().video,
            arcen_media::VideoConfiguration {
                bit_depth: arcen_media::BitDepth::Ten,
                ..arcen_media::VideoConfiguration::legacy_h264()
            },
            "an override must replace only its own axis, leaving the rest of the preset intact"
        );

        // Overrides beat the preset even when, together, they contradict it
        // entirely.
        let full_override = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides {
                codec: Some(arcen_media::VideoCodec::H265),
                chroma: Some(arcen_media::ChromaSubsampling::Yuv444),
                bit_depth: Some(arcen_media::BitDepth::Ten),
                range: Some(arcen_media::ColorRange::Full),
                matrix: Some(arcen_media::ColorMatrix::Bt709),
            },
            variant_override: None,
        };
        assert_eq!(
            full_override.resolved_variant(),
            arcen_media::video::VideoVariant::new(
                arcen_media::VideoConfiguration::grading_reference()
            ),
            "every axis overridden must match the Grading Reference contract exactly"
        );

        // An explicit variant override beats both the preset and every
        // individual axis override, however they disagree with it -- this is
        // the seam the w0 testing machine drives to reach any probe-matrix
        // row directly.
        let explicit_variant =
            arcen_media::video::VideoVariant::from_id("hevc-444-10-full-identity")
                .expect("the identity row is a coherent, documented probe-matrix id");
        let variant_wins = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides {
                codec: Some(arcen_media::VideoCodec::Av1),
                ..ColorFidelityOverrides::default()
            },
            variant_override: Some(explicit_variant),
        };
        assert_eq!(
            variant_wins.resolved_variant(),
            explicit_variant,
            "an explicit variant override must win over both the preset and any axis override"
        );
    }

    /// `resolved_variant` applies each `overrides` axis independently and
    /// does not cross-check the combined result -- deliberately, since an
    /// explicit `variant_override` (which *is* always coherent, checked by
    /// `VideoVariant::from_id`) already covers "drive an exact, valid row".
    /// Callers that need a guaranteed-offered result out of `overrides` must
    /// check `is_coherent()` themselves; this test documents and pins that
    /// contract rather than leaving it an unstated surprise.
    #[test]
    fn color_fidelity_axis_overrides_are_not_cross_validated_for_coherence() {
        // The Standard preset's 4:2:0 chroma plus an identity-matrix
        // override, with no accompanying chroma override, is a combination
        // `arcen_media` does not offer (an identity matrix requires 4:4:4).
        let incoherent = ColorFidelitySettings {
            preset: ColorFidelity::Standard,
            overrides: ColorFidelityOverrides {
                matrix: Some(arcen_media::ColorMatrix::Identity),
                ..ColorFidelityOverrides::default()
            },
            variant_override: None,
        };
        let resolved = incoherent.resolved_variant();
        assert_eq!(
            resolved.video.chroma,
            arcen_media::ChromaSubsampling::Yuv420
        );
        assert_eq!(resolved.video.matrix, arcen_media::ColorMatrix::Identity);
        assert!(
            !resolved.is_coherent(),
            "this exact axis combination is expected to be incoherent -- if `arcen_media` ever \
             starts offering it, update this test's premise rather than treating the assertion \
             as newly broken"
        );
    }

    /// A `CertInfo` for a specific endpoint, reusing the shared fixture's digests.
    fn certificate_info_fixture(endpoint: &str) -> CertInfo {
        let mut info = test_cert_info();
        info.endpoint = endpoint.to_string();
        info.server_name = endpoint.split(':').next().unwrap_or(endpoint).to_string();
        info
    }

    #[test]
    fn a_remembered_pin_outlives_the_process_and_pre_empts_the_prompt() {
        // The whole point of trust-on-first-use is that a *change* after the
        // first visit is a hard failure. That needs a baseline that survives a
        // relaunch; without one, an impostor's fresh certificate raises exactly
        // the dialog the real host raised yesterday.
        let dir = test_config_dir("arcen-remembered-pin");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());

        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "pier.example.internal".to_string();
        draft.port = 18_444;
        let endpoint = connection_endpoint(&draft);
        let info = certificate_info_fixture(&endpoint);

        {
            let mut app = ArcenApp::from_config_repository(repository.clone());
            app.security_mode = SecurityMode::Medium;
            app.trust_certificate_permanently(&draft, &info);
        }

        // A brand new app, as if the user had quit and relaunched.
        let mut reopened = ArcenApp::from_config_repository(repository);
        reopened.security_mode = SecurityMode::Medium;
        assert_eq!(
            reopened.effective_tls_pin(&endpoint),
            Some(info.spki_sha256),
            "the remembered identity did not survive a restart"
        );

        // And it must actually reach the connect path as a pin, because a pin
        // installs PinningVerifier instead of TofuVerifier -- which is what
        // makes a changed identity terminal rather than re-promptable.
        let (options, _) = reopened.connect_options_with_stream_sizing_policy(&draft, None);
        assert!(
            matches!(
                options.tls.mode,
                crate::transport::tls::TlsTrustMode::TofuPinned { .. }
            ),
            "a remembered host must connect pinned, got {:?}",
            options.tls.mode
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn trusting_once_does_not_survive_a_restart() {
        // The two choices must be genuinely different, or the dialog is lying.
        let dir = test_config_dir("arcen-session-only-pin");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());

        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "pier.example.internal".to_string();
        draft.port = 18_444;
        let endpoint = connection_endpoint(&draft);
        let info = certificate_info_fixture(&endpoint);

        {
            let app = ArcenApp::from_config_repository(repository.clone());
            app.trust_certificate_for_session(&draft, &info);
            assert_eq!(app.effective_tls_pin(&endpoint), Some(info.spki_sha256));
        }

        let reopened = ArcenApp::from_config_repository(repository);
        assert_eq!(
            reopened.effective_tls_pin(&endpoint),
            None,
            "session-only trust must not be written to disk"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn high_security_ignores_a_remembered_pin() {
        // High means "a public CA must vouch for this host". A pin the user
        // approved under Medium must not quietly satisfy that.
        let dir = test_config_dir("arcen-remembered-high");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());

        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "pier.example.internal".to_string();
        draft.port = 18_444;
        let info = certificate_info_fixture(&connection_endpoint(&draft));

        let mut app = ArcenApp::from_config_repository(repository);
        app.trust_certificate_permanently(&draft, &info);
        app.security_mode = SecurityMode::High;

        let (options, _) = app.connect_options_with_stream_sizing_policy(&draft, None);
        assert!(
            !matches!(
                options.tls.mode,
                crate::transport::tls::TlsTrustMode::TofuPinned { .. }
            ),
            "High must not be satisfied by a remembered pin, got {:?}",
            options.tls.mode
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_remembered_pin_is_scoped_to_its_own_endpoint() {
        // A pin for one host must never authorise another, or remembering one
        // machine would silently vouch for the whole network.
        let dir = test_config_dir("arcen-remembered-scope");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());

        let mut trusted = ConnectionDraft::new(ConnectionKind::DirectMachine);
        trusted.host = "trusted.example.internal".to_string();
        trusted.port = 18_444;
        let info = certificate_info_fixture(&connection_endpoint(&trusted));

        let mut other = ConnectionDraft::new(ConnectionKind::DirectMachine);
        other.host = "other.example.internal".to_string();
        other.port = 18_444;

        let mut app = ArcenApp::from_config_repository(repository);
        app.trust_certificate_permanently(&trusted, &info);

        assert!(app
            .effective_tls_pin(&connection_endpoint(&trusted))
            .is_some());
        assert_eq!(
            app.effective_tls_pin(&connection_endpoint(&other)),
            None,
            "a pin leaked to a different host"
        );

        // Same host, different port is a different endpoint too.
        let mut different_port = trusted.clone();
        different_port.port = 18_445;
        assert_eq!(
            app.effective_tls_pin(&connection_endpoint(&different_port)),
            None,
            "a pin leaked across ports"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn color_fidelity_unknown_and_corrupt_values_fall_back_safely() {
        let dir = test_config_dir("arcen-color-fidelity-corrupt");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());
        std::fs::write(
            dir.join("settings.json"),
            r#"{
                "color_fidelity": "not_a_real_preset",
                "color_fidelity_codec_override": "vvc",
                "color_fidelity_chroma_override": 444,
                "color_fidelity_bit_depth_override": "9",
                "color_fidelity_range_override": "studio",
                "color_fidelity_matrix_override": "smpte240m",
                "color_fidelity_variant_override": "not-a-real-variant-id"
            }"#,
        )
        .unwrap();

        let loaded = load_client_settings(&repository)
            .expect("a corrupt colour-fidelity section must not fail closed");
        assert_eq!(
            loaded.color_fidelity,
            ColorFidelitySettings::default(),
            "every unrecognised colour-fidelity value must fall back to Standard with no \
             overrides and no explicit variant, never panic, and never invent an arbitrary \
             contract"
        );

        // The same fallback holds one component at a time, directly against
        // the underlying parsers `load_client_settings` relies on.
        assert_eq!(ColorFidelity::from_key("bogus"), ColorFidelity::Standard);
        assert_eq!(arcen_media::VideoCodec::from_token("bogus"), None);
        assert_eq!(arcen_media::ChromaSubsampling::from_token("bogus"), None);
        assert_eq!(arcen_media::BitDepth::from_token("bogus"), None);
        assert_eq!(arcen_media::ColorRange::from_token("bogus"), None);
        assert_eq!(arcen_media::ColorMatrix::from_token("bogus"), None);
        assert!(arcen_media::video::VideoVariant::from_id("bogus").is_err());

        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn encode_intent_survives_a_legacy_or_unreadable_settings_file() {
        // Two failure modes with the same required answer. A settings.json
        // written before this setting existed has no `encode_intent` key at
        // all; one written by a newer build (or hand-edited) may carry a
        // token this build cannot read. Neither may invent grading intent
        // for a user who never asked for it -- the added latency would look
        // like a regression, not a setting.
        let dir = test_config_dir("arcen-encode-intent-migration");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let repository = ClientConfigRepository::at(dir.clone());
        std::fs::write(
            dir.join("settings.json"),
            r#"{"clipboard_enabled":false,"a_future_field_this_version_does_not_know":42}"#,
        )
        .unwrap();

        let legacy = load_client_settings(&repository).unwrap();
        assert_eq!(
            legacy.encode_intent,
            arcen_media::EncodeIntent::Interactive,
            "a missing key must migrate to the latency-first default",
        );
        assert!(!legacy.clipboard_enabled);

        // Saving records the token without disturbing the unknown future
        // field, exactly as the colour keys do.
        save_client_settings(&repository, &legacy).unwrap();
        let saved: serde_json::Value =
            serde_json::from_slice(&std::fs::read(dir.join("settings.json")).unwrap()).unwrap();
        assert_eq!(
            saved.get("encode_intent"),
            Some(&serde_json::Value::from("interactive"))
        );
        assert_eq!(
            saved.get("a_future_field_this_version_does_not_know"),
            Some(&serde_json::Value::from(42))
        );

        for unreadable in [r#""lossless""#, "7", "null"] {
            std::fs::write(
                dir.join("settings.json"),
                format!(r#"{{"encode_intent":{unreadable}}}"#),
            )
            .unwrap();
            assert_eq!(
                load_client_settings(&repository).unwrap().encode_intent,
                arcen_media::EncodeIntent::Interactive,
                "an unreadable intent ({unreadable}) must fall back, never fail the load",
            );
        }
        assert_eq!(arcen_media::EncodeIntent::from_token("lossless"), None);

        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn changed_pin_is_terminal_and_does_not_start_replacement_probe() {
        let mut app = ArcenApp {
            security_mode: SecurityMode::Medium,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "tofu-host.local".to_string();
        draft.username = "artist".to_string();
        draft.password = "secret".to_string();
        let endpoint = connection_endpoint(&draft);
        app.accepted_tls_pins.lock().unwrap().insert(
            endpoint.clone(),
            arcen_transport::tls::TlsPin::new(
                arcen_transport::tls::PinKind::SubjectPublicKeyInfoSha256,
                [0x42; 32],
            ),
        );
        app.accepted_tls_pins.lock().unwrap().insert(
            "other.local:18443".to_string(),
            arcen_transport::tls::TlsPin::new(
                arcen_transport::tls::PinKind::SubjectPublicKeyInfoSha256,
                [0x44; 32],
            ),
        );
        app.pending_connection = Some(draft.clone());
        app.active_connection = Some(draft.clone());
        app.screen = AppScreen::Connecting(draft);

        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::TlsIdentity),
                message: format!(
                    "TLS error: {}",
                    crate::transport::tls::TOFU_PIN_MISMATCH_ERROR
                ),
                observed_at: Instant::now(),
            }),
            0,
            &egui::Context::default(),
        );

        assert!(app
            .accepted_tls_pins
            .lock()
            .unwrap()
            .contains_key(&endpoint));
        assert!(app
            .accepted_tls_pins
            .lock()
            .unwrap()
            .contains_key("other.local:18443"));
        assert!(matches!(app.screen, AppScreen::Home));
    }

    #[test]
    fn configured_pin_mismatch_fails_closed_without_reprobe() {
        let mut app = ArcenApp {
            security_mode: SecurityMode::Medium,
            ..ArcenApp::default()
        };
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "pinned-host.local".to_string();
        draft.tls_trust = Some(TlsTrustConfig::pinned_certificate([0x42; 32]));
        app.pending_connection = Some(draft.clone());
        app.active_connection = Some(draft.clone());
        app.screen = AppScreen::Connecting(draft);

        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::TlsIdentity),
                message: format!(
                    "TLS error: {}",
                    crate::transport::tls::TOFU_PIN_MISMATCH_ERROR
                ),
                observed_at: Instant::now(),
            }),
            0,
            &egui::Context::default(),
        );

        assert!(app.status.contains("TLS error"));
        assert!(app.accepted_tls_pins.lock().unwrap().is_empty());
        assert!(!matches!(app.screen, AppScreen::Connecting(_)));
    }

    #[test]
    fn expired_resume_returns_to_credentials() {
        let mut app = ArcenApp::default();
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "pier.example.internal".to_string();
        app.pending_connection = Some(draft.clone());
        app.active_connection = Some(draft.clone());
        app.screen = AppScreen::Connecting(draft);

        app.handle_connection_closed(
            Some(SessionEnd {
                reason: DisconnectReason::Terminal(TerminalDisconnect::Resume(Some(
                    ResumeErrorCode::Expired,
                ))),
                message: "resume rejected: bounded resume window ended".to_string(),
                observed_at: Instant::now(),
            }),
            0,
            &egui::Context::default(),
        );

        // An expired resume grant means the bounded reconnect window closed, so
        // the user authenticates again. This used to be special-cased into a
        // "renew your licence" dead end; there is no licence, and asking for
        // credentials is the correct and only recovery.
        assert!(matches!(app.screen, AppScreen::Credentials(_)));
    }

    #[test]
    fn reconnect_screen_mirrors_controller_overlay_and_manual_cancel() {
        struct FixedJitter;
        impl crate::reconnect::JitterSource for FixedJitter {
            fn inclusive(&mut self, _minimum: Duration, maximum: Duration) -> Option<Duration> {
                Some(maximum)
            }
        }

        let identity = ConnectionIdentity {
            endpoint: "wss://pier:18443".to_string(),
            security: "medium:pin".to_string(),
            topology: "direct:display".to_string(),
        };
        let mut controller = ReconnectController::new(9, identity, "nonce".to_string());
        controller
            .accept_initial(
                Some("grant".to_string()),
                Some(Duration::from_secs(30)),
                false,
                "sid".to_string(),
            )
            .unwrap();
        controller
            .schedule(
                "connection reset".to_string(),
                Duration::ZERO,
                &mut FixedJitter,
            )
            .unwrap();

        let mut app = ArcenApp {
            connection_generation: 9,
            reconnect: Some(controller),
            ..ArcenApp::default()
        };
        app.refresh_reconnect_screen();
        let AppScreen::Reconnecting(overlay) = &app.screen else {
            panic!("expected reconnect overlay");
        };
        assert_eq!(overlay.attempt, 1);
        assert_eq!(overlay.next_retry, Some(Duration::from_millis(250)));
        assert_eq!(overlay.deadline, Duration::from_secs(30));
        assert_eq!(overlay.last_error, "connection reset");

        app.disconnect();
        assert!(app.reconnect.is_none());
    }

    #[test]
    fn drive_reconnect_ignores_live_display_drift_while_connected_and_leaves_the_session_alone() {
        // Live blocker fix (end-to-end through the real `drive_reconnect`
        // call site, not just `take_due` in isolation): a `Connected`
        // controller (nothing has actually disconnected) must survive live
        // identity drift every frame -- this is both "initial Deck start
        // with live-vs-baseline display drift does not drop the session"
        // and "active topology changes are handled by the multi-window
        // session path, not the reconnect controller" (`drive_reconnect`
        // never touches multi-window state either way; teardown-on-
        // topology-loss is exclusively `multi_window_failure`'s job).
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "multi-monitor-host.local".to_string();
        let options = connect_options_from_draft(&draft);

        // Deliberately mismatched baseline: the real `connection_identity`
        // recomputed from `draft`/`options` above can never produce this
        // endpoint, so the mismatch is deterministic and does not depend on
        // this test machine's actual live display hardware.
        let stale_baseline_identity = ConnectionIdentity {
            endpoint: "quic://stale-baseline-host:0".to_string(),
            security: "bogus:baseline".to_string(),
            topology: "bogus:baseline".to_string(),
        };
        let mut controller =
            ReconnectController::new(3, stale_baseline_identity, "nonce".to_string());
        controller
            .accept_initial(
                Some("grant".to_string()),
                Some(Duration::from_secs(30)),
                false,
                "sid".to_string(),
            )
            .unwrap();
        assert_eq!(controller.phase(), &ReconnectPhase::Connected);

        let mut app = ArcenApp {
            connection_generation: 3,
            active_connection: Some(draft),
            reconnect_options: Some(options),
            reconnect: Some(controller),
            screen: AppScreen::InSession,
            ..ArcenApp::default()
        };

        app.drive_reconnect(&egui::Context::default());

        assert!(
            app.reconnect.is_some(),
            "a Connected controller must survive live identity drift, not be dropped"
        );
        assert_eq!(
            app.reconnect.as_ref().unwrap().phase(),
            &ReconnectPhase::Connected,
            "must remain Connected, never terminalized by live drift"
        );
        assert!(
            matches!(app.screen, AppScreen::InSession),
            "the live session must stay in session, never bounced to Credentials/Home, got {:?}",
            app.screen
        );
    }

    /// Builds a `ReconnectController` whose `schedule` call will succeed
    /// (an accepted initial credential with a live detach window), for
    /// `multi_window_failure` tests that need to prove reconnect is
    /// genuinely preserved/scheduled rather than cancelled.
    fn schedule_capable_reconnect_controller(generation: u64) -> ReconnectController {
        let identity = ConnectionIdentity {
            endpoint: "wss://pier:18443".to_string(),
            security: "medium:pin".to_string(),
            topology: "direct:display".to_string(),
        };
        let mut controller = ReconnectController::new(generation, identity, "nonce".to_string());
        controller
            .accept_initial(
                Some("grant".to_string()),
                Some(Duration::from_secs(30)),
                false,
                "sid".to_string(),
            )
            .expect("accept_initial succeeds for a fresh controller");
        controller
    }

    #[test]
    fn multi_window_failure_schedules_reconnect_and_shows_reconnecting_screen_when_permitted() {
        // Audit finding #3: a multi-window topology failure must never call
        // a silent manual `disconnect()` -- it must preserve/schedule a
        // reconnect when this generation's controller still permits one,
        // landing on `AppScreen::Reconnecting`, never leaving the prior
        // `AppScreen::InSession` behind and never falling all the way back
        // to Home the way a genuinely-cancelled reconnect would.
        let generation = 9;
        let mut app = ArcenApp {
            connection_generation: generation,
            reconnect: Some(schedule_capable_reconnect_controller(generation)),
            screen: AppScreen::InSession,
            ..ArcenApp::default()
        };

        let outcome =
            app.multi_window_failure(&egui::Context::default(), "committed roster went non-live");

        assert_eq!(
            outcome,
            MultiWindowFailureOutcome::ReconnectScheduled,
            "typed outcome must reflect that a reconnect was actually scheduled",
        );
        assert!(
            matches!(app.screen, AppScreen::Reconnecting(_)),
            "expected a Reconnecting overlay, got {:?}",
            app.screen
        );
        assert!(
            !matches!(app.screen, AppScreen::InSession),
            "no stale in-session screen must survive a multi-window failure",
        );
        assert!(
            app.reconnect.is_some(),
            "the reconnect controller must be preserved, not cancelled, when it schedules",
        );
        assert!(app.status.contains("committed roster went non-live"));
    }

    #[test]
    fn multi_window_failure_falls_back_to_home_when_reconnect_is_unavailable() {
        let mut app = ArcenApp {
            screen: AppScreen::InSession,
            active_connection: None,
            reconnect: None,
            ..ArcenApp::default()
        };

        let outcome = app.multi_window_failure(&egui::Context::default(), "enter timed out");

        assert_eq!(
            outcome,
            MultiWindowFailureOutcome::ReturnedToCredentialsOrHome,
            "typed outcome must reflect the return-to-credentials/home path taken",
        );
        assert!(
            matches!(app.screen, AppScreen::Home),
            "expected Home with no surviving connection draft, got {:?}",
            app.screen
        );
        assert!(!matches!(app.screen, AppScreen::InSession));
        assert!(app.reconnect.is_none());
    }

    #[test]
    fn multi_window_failure_falls_back_to_credentials_when_a_draft_survives_and_reconnect_is_unavailable(
    ) {
        let mut draft = ConnectionDraft::new(ConnectionKind::DirectMachine);
        draft.host = "multi-monitor-host.local".to_string();
        let mut app = ArcenApp {
            screen: AppScreen::InSession,
            active_connection: Some(draft),
            reconnect: None,
            ..ArcenApp::default()
        };

        let outcome =
            app.multi_window_failure(&egui::Context::default(), "multi-window entry aborted");

        assert_eq!(
            outcome,
            MultiWindowFailureOutcome::ReturnedToCredentialsOrHome,
            "typed outcome must reflect the return-to-credentials/home path taken",
        );
        assert!(
            matches!(app.screen, AppScreen::Credentials(_)),
            "expected Credentials with a surviving connection draft, got {:?}",
            app.screen
        );
        assert!(!matches!(app.screen, AppScreen::InSession));
    }

    /// Regression test for the USB enumeration race: if `wacom_usb_presence()`
    /// returned Unknown/Unavailable at `apply_server_hello` time (provisional
    /// `pen_negotiated = false`), `apply_tablet_mode_result` must still honour
    /// the host's authoritative `LocalTermination` result and set
    /// `pen_negotiated = true`.
    #[test]
    fn pen_negotiated_set_authoritatively_from_tablet_mode_result_despite_provisional_false() {
        use crate::protocol::messages::INPUT_PROTOCOL_VERSION;

        let generation = 7_u64;
        let mut app = ArcenApp {
            connection_generation: generation,
            tablet_mode_requested: TabletModeMsg::LocalTermination,
            // Simulates the race: provisional was false because USB was not
            // detected at hello time.
            pen_negotiated: false,
            tablet_mode_active: TabletModeMsg::DisabledMouseCompat,
            tablet_input_enabled: false,
            // Simulate hello-time state: host advertised pen available, local
            // USB detection was Unknown.
            hello_input_protocol_version: INPUT_PROTOCOL_VERSION,
            hello_pen_capability: InputCapabilityAvailability::Available,
            hello_local_pen_capability: InputCapabilityAvailability::Unknown,
            ..ArcenApp::default()
        };

        app.apply_tablet_mode_result(
            TabletModeResultMsg {
                requested: TabletModeMsg::LocalTermination,
                active: TabletModeMsg::LocalTermination,
                accepted: true,
                ..TabletModeResultMsg::default()
            },
            generation,
        );

        assert_eq!(app.tablet_mode_active, TabletModeMsg::LocalTermination);
        assert!(app.tablet_input_enabled, "tablet input must be enabled");
        assert!(
            app.pen_negotiated,
            "pen_negotiated must be true after authoritative LocalTermination result \
             even though provisional was false (USB enumeration race)",
        );
    }

    /// Ensure that if the host sends LocalTermination but hello_pen_capability
    /// is NOT Available, pen_negotiated stays false (host lied or downgraded).
    #[test]
    fn pen_negotiated_stays_false_if_host_pen_capability_not_available() {
        use crate::protocol::messages::INPUT_PROTOCOL_VERSION;

        let generation = 8_u64;
        let mut app = ArcenApp {
            connection_generation: generation,
            tablet_mode_requested: TabletModeMsg::LocalTermination,
            pen_negotiated: false,
            tablet_mode_active: TabletModeMsg::DisabledMouseCompat,
            tablet_input_enabled: false,
            hello_input_protocol_version: INPUT_PROTOCOL_VERSION,
            hello_pen_capability: InputCapabilityAvailability::Unavailable,
            hello_local_pen_capability: InputCapabilityAvailability::Available,
            ..ArcenApp::default()
        };

        app.apply_tablet_mode_result(
            TabletModeResultMsg {
                requested: TabletModeMsg::LocalTermination,
                active: TabletModeMsg::LocalTermination,
                accepted: true,
                ..TabletModeResultMsg::default()
            },
            generation,
        );

        assert!(
            !app.pen_negotiated,
            "host pen unavailable → pen_negotiated must stay false"
        );
    }

    // ---------------------------------------------------------------
    // Production Carrier A multi-window wiring
    // (`begin_multi_window_if_applicable`/`drive_multi_window`/
    // `arm_multi_window_decode_isolation`/`dispatch_secondary_pointer`/
    // `close_multi_window_session`).
    //
    // `crate::ui::multi_window::multi_window_runtime_available()` now
    // returns `true` in production (see that module's own doc). Most tests
    // below still exercise the wiring directly against `ArcenApp`'s own
    // fields/methods (constructing `MultiWindowSessionState::Active`
    // in-place, driving `drive_multi_window`/input dispatch directly, etc.)
    // rather than always starting from a real `ServerHello` round trip,
    // since that is the more precise, less redundant way to cover each
    // method's own contract in isolation. `begin_multi_window_if_applicable_*`
    // below is the one pair that proves the real entry point itself, end to
    // end: a valid applied topology begins a live entry, and a legacy/
    // no-capability hello never does.
    //
    // Every fake `cg_display_id` used below is a sentinel far outside any
    // real `CGDirectDisplayID` range, so `viewport_builder_for`/
    // `crate::ui::multi_window_runtime::live_active_displays` can never
    // accidentally resolve it on real hardware -- these tests are
    // deterministic in CI and on a developer's own multi-monitor desk
    // alike, and never open a real native window.
    // ---------------------------------------------------------------

    const FAKE_CG_DISPLAY_ID_PRIMARY: u32 = 0xFFFF_FFF1;
    const FAKE_CG_DISPLAY_ID_SECONDARY: u32 = 0xFFFF_FFF2;

    fn test_media_roster(ids: &[u16]) -> Box<arcen_media::RegionMediaRoster> {
        let dimensions = ids
            .iter()
            .copied()
            .map(|id| (id, 1920, 1080))
            .collect::<Vec<_>>();
        test_media_roster_with_dimensions(&dimensions)
    }

    fn test_media_roster_with_dimensions(
        dimensions: &[(u16, u32, u32)],
    ) -> Box<arcen_media::RegionMediaRoster> {
        let plans = dimensions
            .iter()
            .copied()
            .map(|(id, width, height)| {
                arcen_media::RegionMediaPlan::new(
                    arcen_media::SessionMonitorId::new(id).expect("valid session monitor id"),
                    arcen_media::MediaStreamEpoch::new(u64::from(id)).expect("valid stream epoch"),
                    arcen_media::video::EncoderBackend::OpenH264,
                    arcen_media::VideoConfiguration::legacy_h264(),
                    width,
                    height,
                    60,
                    arcen_media::BitrateBudgetKbps::nominal_for_geometry(width, height, 60),
                )
                .expect("valid media plan")
            })
            .collect();
        Box::new(arcen_media::RegionMediaRoster::new(plans).expect("valid media roster"))
    }

