    #[test]
    fn sync_media_state_root_frame_flows_immediately_when_multi_window_is_inactive() {
        // Legacy/single-monitor sessions (Primary Display Only, Windowed, or
        // Match My Layout with a single local display -- any of which leave
        // `self.multi_window` `Inactive` because multi-monitor-v1 was never
        // requested) must be completely unaffected by the pending-gate
        // above: root's frame uploads and InSession flips immediately,
        // exactly as before. A host lacking/declining a genuine
        // multi-monitor-v1 request is not one of these cases: that fails
        // the connection during auth, so no live session with a received
        // frame ever reaches this state through that path.
        let generation = 10;
        let mut app = ArcenApp {
            connection_generation: generation,
            screen: AppScreen::LaunchingSession(ConnectionDraft::new(
                ConnectionKind::DirectMachine,
            )),
            ..ArcenApp::default()
        };
        assert!(matches!(
            app.multi_window,
            MultiWindowSessionState::Inactive
        ));
        let shared = Arc::new(Mutex::new(SharedMediaState {
            latest_frame: Some(DecodedVideoFrame {
                width: 2,
                height: 2,
                rgba: vec![255; 2 * 2 * 4],
                timestamp_ms: 0,
                pixel_format: "bgra".to_string(),
                backend: "test",
                native: None,
            }),
            generation,
            ..SharedMediaState::default()
        }));
        app.media = Some(shared);

        app.sync_media_state(&egui::Context::default());

        assert!(app.remote_texture.is_some());
        assert!(matches!(app.screen, AppScreen::InSession));
        assert!(app.pending_root_frame.is_none());
    }

    #[test]
    fn sync_media_state_prefers_a_fresh_frame_over_an_older_buffered_root_frame_and_never_replays_it(
    ) {
        // Release-candidate media finding #2: `pending_root_frame` must
        // always be taken (and cleared) on a non-pending sync regardless of
        // whether a fresh frame also arrived this same poll -- the old
        // `frame.or_else(|| self.pending_root_frame.take())` short-circuited
        // and left a stale buffered frame in place whenever `frame` was
        // already `Some`, letting it wrongly resurface on some *later* poll
        // after something newer had already published. This proves: (1) a
        // strictly older buffered frame loses to a fresh one that arrives in
        // the same sync, and (2) the buffer is empty afterward, so the very
        // next poll (with no fresh frame at all) publishes nothing more --
        // the old frame is discarded outright, never replayed.
        let generation = 11;
        let mut app = ArcenApp {
            connection_generation: generation,
            screen: AppScreen::LaunchingSession(ConnectionDraft::new(
                ConnectionKind::DirectMachine,
            )),
            pending_root_frame: Some(DecodedVideoFrame {
                width: 2,
                height: 2,
                rgba: vec![255; 2 * 2 * 4],
                timestamp_ms: 1,
                pixel_format: "bgra".to_string(),
                backend: "test",
                native: None,
            }),
            ..ArcenApp::default()
        };
        assert!(matches!(
            app.multi_window,
            MultiWindowSessionState::Inactive
        ));
        let shared = Arc::new(Mutex::new(SharedMediaState {
            latest_frame: Some(DecodedVideoFrame {
                width: 4,
                height: 4,
                rgba: vec![255; 4 * 4 * 4],
                timestamp_ms: 5,
                pixel_format: "bgra".to_string(),
                backend: "test",
                native: None,
            }),
            generation,
            ..SharedMediaState::default()
        }));
        app.media = Some(shared.clone());

        app.sync_media_state(&egui::Context::default());

        assert_eq!(
            app.remote_frame_size,
            Some([4, 4]),
            "the fresh frame must win over the older buffered one, not the reverse",
        );
        assert!(
            app.pending_root_frame.is_none(),
            "the buffered frame must be taken and cleared on this sync regardless of the fresh \
             frame's presence",
        );

        // Next poll: no fresh frame queued at all. If the old buffered frame
        // had survived (the pre-fix bug), it would republish here.
        shared.lock().expect("media state poisoned").latest_frame = None;
        app.remote_frame_size = None;
        app.sync_media_state(&egui::Context::default());

        assert_eq!(
            app.remote_frame_size, None,
            "the discarded older frame must never be replayed on a later poll",
        );
    }

    #[test]
    fn sync_media_state_publishes_a_buffered_root_frame_exactly_once_when_no_fresh_frame_arrives() {
        // Companion case: only a buffered `pending_root_frame` exists (e.g.
        // left over from a just-committed multi-window transaction with no
        // brand new frame yet) -- it must still publish on this sync, and
        // then never republish on a subsequent poll once consumed.
        let generation = 12;
        let mut app = ArcenApp {
            connection_generation: generation,
            screen: AppScreen::LaunchingSession(ConnectionDraft::new(
                ConnectionKind::DirectMachine,
            )),
            pending_root_frame: Some(DecodedVideoFrame {
                width: 3,
                height: 3,
                rgba: vec![255; 3 * 3 * 4],
                timestamp_ms: 2,
                pixel_format: "bgra".to_string(),
                backend: "test",
                native: None,
            }),
            ..ArcenApp::default()
        };
        let shared = Arc::new(Mutex::new(SharedMediaState {
            generation,
            ..SharedMediaState::default()
        }));
        app.media = Some(shared.clone());

        app.sync_media_state(&egui::Context::default());

        assert_eq!(app.remote_frame_size, Some([3, 3]));
        assert!(app.pending_root_frame.is_none());

        app.remote_frame_size = None;
        app.sync_media_state(&egui::Context::default());

        assert_eq!(
            app.remote_frame_size, None,
            "a consumed buffered frame must publish exactly once, never a second time",
        );
    }

