    /// Whether `shapes` (a real, un-tessellated `FullOutput.shapes` from a
    /// driven pass) contains any shape that paints with exactly
    /// `texture_id` -- i.e. whether a secondary viewport's decoded video
    /// frame was actually drawn on screen this pass, as opposed to only a
    /// neutral placeholder fill. `ui.painter().image(...)` always produces
    /// `Shape::Mesh` (see `epaint::Shape::image`); `rect_filled` never does,
    /// so this is an exact, unambiguous test for "was any remote frame
    /// exposed", not a heuristic.
    fn shapes_reference_texture(
        shapes: &[egui::epaint::ClippedShape],
        texture_id: egui::TextureId,
    ) -> bool {
        shapes
            .iter()
            .any(|clipped| shape_references_texture(&clipped.shape, texture_id))
    }

    fn shape_references_texture(shape: &egui::Shape, texture_id: egui::TextureId) -> bool {
        match shape {
            egui::Shape::Vec(nested) => nested
                .iter()
                .any(|inner| shape_references_texture(inner, texture_id)),
            egui::Shape::Mesh(mesh) => mesh.texture_id == texture_id,
            _ => false,
        }
    }

    #[test]
    fn drive_multi_window_consumes_a_secondary_frame_from_the_shared_map_even_when_the_viewport_cannot_be_resolved(
    ) {
        // Environment-independent companion to
        // `drive_multi_window_secondary_texture_uploads_only_on_a_fresh_decoded_frame_not_every_repaint`:
        // `secondary_frames.remove(&monitor_id)` happens unconditionally at
        // the very top of each per-assignment loop iteration in
        // `drive_multi_window`, strictly before the (possibly-failing)
        // `viewport_builder_for` resolution check -- so a frame is consumed
        // out of the shared map regardless of whether this dev environment
        // has a real second display to actually paint it on. This proves
        // the "must be taken, not cloned" contract directly, without
        // depending on live hardware displays.
        let validated = two_monitor_validated_topology();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp::default();
        let shared = Arc::new(Mutex::new(SharedMediaState::fresh(1, false)));
        shared
            .lock()
            .expect("media state poisoned")
            .secondary_frames
            .insert(
                monitor_id,
                DecodedVideoFrame {
                    width: 2,
                    height: 2,
                    rgba: vec![255; 2 * 2 * 4],
                    timestamp_ms: 0,
                    pixel_format: "bgra".to_string(),
                    backend: "test",
                    native: None,
                },
            );
        app.media = Some(Arc::clone(&shared));
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: true,
        };
        app.multi_window_started_at = Some(Instant::now());

        app.drive_multi_window(&egui::Context::default());

        assert!(
            shared
                .lock()
                .expect("media state poisoned")
                .secondary_frames
                .get(&monitor_id)
                .is_none(),
            "the frame must be removed from the shared map on read, not merely cloned in place, \
             even when the target display cannot currently be resolved",
        );
    }

    #[test]
    fn drive_multi_window_secondary_paint_shows_no_remote_frame_until_commit_then_publishes_atomically(
    ) {
        // Finding #3 (final runtime issues): decode/upload may keep
        // arming/buffering a secondary's texture pre-commit, but the
        // *painted* output must never expose any of it until every
        // root+secondary window has confirmed and the transaction has
        // committed -- then it must show up immediately (same pass the
        // commit is already reflected), not lag another frame behind.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.len() < 2 {
            eprintln!(
                "skipping: need at least 2 live active displays in this environment to reach a \
                 genuinely resolved (non-hard-failing) secondary viewport whose closure actually \
                 runs and paints",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        let secondary_display_id = live_display_ids[1];
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: monitor_id,
                        cg_display_id: secondary_display_id,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3840,
                    height_px: 1080,
                },
            }
        };
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp::default();
        let shared = Arc::new(Mutex::new(SharedMediaState::fresh(1, false)));
        shared
            .lock()
            .expect("media state poisoned")
            .secondary_frames
            .insert(
                monitor_id,
                DecodedVideoFrame {
                    width: 2,
                    height: 2,
                    rgba: vec![255; 2 * 2 * 4],
                    timestamp_ms: 0,
                    pixel_format: "bgra".to_string(),
                    backend: "test",
                    native: None,
                },
            );
        app.media = Some(shared);
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.multi_window_started_at = Some(Instant::now());

        // Pending pass: a real decoded frame is already available and gets
        // buffered/uploaded into `secondary_textures` (decode isolation's
        // own early arming continues exactly as designed), but nothing may
        // be painted from it yet.
        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            time: Some(0.0),
            ..Default::default()
        });
        app.drive_multi_window(&ctx);
        let pending_output = ctx.end_pass();
        let buffered_texture_id = app
            .secondary_textures
            .get(&monitor_id)
            .expect("decode isolation must keep buffering/uploading even while pending")
            .id();
        assert!(
            !shapes_reference_texture(&pending_output.shapes, buffered_texture_id),
            "a pending (uncommitted) secondary must never paint its buffered remote frame",
        );

        // Commit (as `drive_multi_window`'s own poll would once every
        // window confirms) and drive one more pass on the *same* egui
        // context: the already-buffered texture must now publish
        // immediately, in this same first committed pass -- no extra lag.
        //
        // Reusing the same `Context` (rather than a fresh one) and pushing
        // `time` well past `Style::animation_time` (0.2s) is required so
        // the embedded-viewport fallback's own window fade-in animation
        // (unrelated to production code under test) has fully settled to
        // opacity 1.0; a brand-new `Context`'s very first-ever frame for a
        // just-created `Area` always starts at opacity 0 -- which egui's
        // own `Painter::add` turns into `Shape::Noop`, an egui-internal
        // test-harness artifact, not a signal about our paint-gating logic.
        if let MultiWindowSessionState::Active { committed, .. } = &mut app.multi_window {
            *committed = true;
        }
        ctx.begin_pass(egui::RawInput {
            time: Some(10.0),
            ..Default::default()
        });
        app.drive_multi_window(&ctx);
        let committed_output = ctx.end_pass();
        let published_texture_id = app
            .secondary_textures
            .get(&monitor_id)
            .expect("still buffered after commit")
            .id();
        assert_eq!(
            buffered_texture_id, published_texture_id,
            "commit must publish the exact frame that was already buffered pre-commit, not a \
             fresh/different one",
        );
        assert!(
            shapes_reference_texture(&committed_output.shapes, published_texture_id),
            "once committed, the secondary must paint its buffered remote frame immediately",
        );
    }

