    /// Regression test for the array-index button mapping bug: secondary
    /// viewports must map middle -> wire button 2 and secondary -> wire
    /// button 3, exactly [`POINTER_BUTTON_WIRE_MAPPING`], never a
    /// positional array index. Presses each of the three wire buttons in
    /// turn and asserts the wire message carries that exact button number.
    #[test]
    fn dispatch_secondary_pointer_maps_middle_and_secondary_to_the_same_wire_codes_as_root() {
        let (mut app, mut receiver) = app_with_command_channel();
        let validated = two_monitor_validated_topology();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");

        for wire_button in [1_u8, 2, 3] {
            let buttons =
                POINTER_BUTTON_WIRE_MAPPING.map(|(_, mapped)| (mapped, mapped == wire_button));
            app.dispatch_secondary_pointer(&validated, monitor_id, (0.5, 0.5), buttons);

            // The move message may or may not be re-sent depending on
            // whether the pointer position changed; only the button
            // message's wire code matters for this regression test.
            let mut saw_expected_button = false;
            while let Ok(command) = receiver.try_recv() {
                let SessionCommand::Json(message) = command else {
                    panic!("expected JSON command");
                };
                assert_direct_region_json(&message);
                if message["type"] == "region_pointer_button" {
                    assert_eq!(
                        message["button"], wire_button,
                        "a press on wire button {wire_button} must be reported as that exact \
                         button, never a different one via positional mixup",
                    );
                    assert_eq!(message["pressed"], true);
                    saw_expected_button = true;
                }
            }
            assert!(
                saw_expected_button,
                "wire button {wire_button} press must be forwarded",
            );

            // Release every button before moving to the next case so each
            // iteration starts from a clean, fully-released state.
            let released = POINTER_BUTTON_WIRE_MAPPING.map(|(_, mapped)| (mapped, false));
            app.dispatch_secondary_pointer(&validated, monitor_id, (0.5, 0.5), released);
            while receiver.try_recv().is_ok() {}
        }
    }

    #[test]
    fn dispatch_secondary_pointer_maps_button_and_position_correctly_on_a_rotated_secondary_monitor(
    ) {
        let (mut app, mut receiver) = app_with_command_channel();
        let validated = two_monitor_validated_topology_with_rotated_secondary();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");

        // Bottom-right corner of the rotated (1440x2560) secondary, pressing
        // wire button 3 (Secondary) -- must never be reported as button 2
        // (the array-index bug Finding #4 fixed) and must resolve to the
        // rotated monitor's own far corner in desktop pixels, not root's.
        app.dispatch_secondary_pointer(
            &validated,
            monitor_id,
            (1.0, 1.0),
            [(1, false), (2, false), (3, true)],
        );

        let enter_msg = receive_json(&mut receiver);
        assert_eq!(enter_msg["type"], "region_pointer_enter");
        assert_eq!(enter_msg["region_id"], 2);
        assert_eq!(enter_msg["logical_x"], 1440 * 120 - 1);
        assert_eq!(enter_msg["logical_y"], 2560 * 120 - 1);
        assert_direct_region_json(&enter_msg);
        let button_msg = receive_region_json(&mut receiver, "region_pointer_button");
        assert_eq!(button_msg["button"], 3);
        assert_eq!(button_msg["pressed"], true);
    }

