    #[test]
    fn dispatch_secondary_scroll_accumulates_sub_tick_deltas_and_forwards_whole_ticks() {
        let (mut app, mut receiver) = app_with_command_channel();
        let validated = two_monitor_validated_topology();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");

        // Less than one full wheel tick (120 units): must accumulate, not send.
        app.dispatch_secondary_scroll(&validated, monitor_id, (0.5, 0.5), egui::vec2(0.0, 50.0));
        assert!(
            receiver.try_recv().is_err(),
            "a sub-tick scroll delta must never be forwarded on its own"
        );

        // The remainder plus this delta crosses one full tick (50 + 80 = 130).
        app.dispatch_secondary_scroll(&validated, monitor_id, (0.5, 0.5), egui::vec2(0.0, 80.0));
        let scroll_msg = receive_region_json(&mut receiver, "region_pointer_scroll");
        assert_eq!(scroll_msg["delta_y"], -120);
        assert_eq!(scroll_msg["delta_x"], 0);
        assert!(receiver.try_recv().is_err(), "only one tick was crossed");
    }

