    #[test]
    fn scroll_accumulation_never_leaks_a_sub_tick_remainder_from_root_to_a_secondary_viewport() {
        // Final gate audit finding #3: root's own scroll accumulator
        // (`root_scroll_accum`) and a secondary's own accumulator
        // (`secondary_scroll_accum`) must be entirely separate storage, so
        // a scroll gesture crossing from root to a secondary never lets a
        // leftover root sub-tick remainder push the secondary across a
        // tick boundary it would not otherwise have crossed on its own.
        let (mut app, mut receiver) = app_with_command_channel();
        let validated = two_monitor_validated_topology();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");

        // Root already holds a large leftover sub-tick remainder from
        // earlier root-focused scrolling (just under one tick).
        app.root_scroll_accum = egui::vec2(0.0, 119.0);

        // Focus now switches to the secondary; its own delta alone (50
        // units) must not inherit root's leftover remainder -- 119 + 50 =
        // 169 would wrongly cross a full tick if the accumulator were
        // shared.
        app.dispatch_secondary_scroll(&validated, monitor_id, (0.0, 0.0), egui::vec2(0.0, 50.0));

        assert!(
            receiver.try_recv().is_err(),
            "a secondary's own scroll accumulation must never be seeded by root's leftover \
             sub-tick remainder",
        );
        assert_eq!(
            app.root_scroll_accum,
            egui::vec2(0.0, 119.0),
            "root's own accumulator must be untouched by a secondary's own dispatch",
        );
        assert_eq!(
            app.secondary_scroll_accum.get(&monitor_id).copied(),
            Some(egui::vec2(0.0, 50.0)),
            "the secondary's own accumulator must hold only its own delta",
        );
    }

    #[test]
    fn scroll_accumulation_never_leaks_between_two_different_secondary_monitors() {
        // Same property as the root -> secondary test above, but crossing
        // from one secondary viewport directly to another (e.g. a pointer
        // dragged across a shared physical edge between two committed
        // secondary monitors).
        let (mut app, mut receiver) = app_with_command_channel();
        use crate::ui::multi_window_session::{
            DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
        };
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let validated = crate::ui::multi_window_session::ValidatedAppliedTopology {
            generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
            carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
            monitors: vec![
                ResolvedAppliedMonitor {
                    session_monitor_id: arcen_media::SessionMonitorId::new(1).expect("valid id"),
                    cg_display_id: FAKE_CG_DISPLAY_ID_PRIMARY,
                    rect: MonitorDesktopRect {
                        x: 0,
                        y: 0,
                        width_px: 1920,
                        height_px: 1080,
                    },
                },
                ResolvedAppliedMonitor {
                    session_monitor_id: monitor_a,
                    cg_display_id: FAKE_CG_DISPLAY_ID_SECONDARY,
                    rect: MonitorDesktopRect {
                        x: 1920,
                        y: 0,
                        width_px: 1920,
                        height_px: 1080,
                    },
                },
                ResolvedAppliedMonitor {
                    session_monitor_id: monitor_b,
                    cg_display_id: 0xFFFF_FFF3,
                    rect: MonitorDesktopRect {
                        x: 3840,
                        y: 0,
                        width_px: 1920,
                        height_px: 1080,
                    },
                },
            ],
            media_roster: test_media_roster(&[1]),
            desktop: DesktopRect {
                x: 0,
                y: 0,
                width_px: 5760,
                height_px: 1080,
            },
        };

        // Monitor A accumulates a large sub-tick remainder just under one
        // tick.
        app.dispatch_secondary_scroll(&validated, monitor_a, (0.0, 0.0), egui::vec2(0.0, 119.0));
        assert!(receiver.try_recv().is_err());

        // Monitor B's own, separate delta is small -- must not inherit
        // monitor A's remainder.
        app.dispatch_secondary_scroll(&validated, monitor_b, (0.0, 0.0), egui::vec2(0.0, 50.0));
        assert!(
            receiver.try_recv().is_err(),
            "monitor B's own scroll accumulation must never be seeded by monitor A's leftover \
             sub-tick remainder",
        );

        // Confirm each monitor's own accumulator independently still holds
        // exactly its own expected remainder -- proving they really are
        // separate slots, not merely "didn't happen to cross a tick yet"
        // by coincidence.
        assert_eq!(
            app.secondary_scroll_accum.get(&monitor_a).copied(),
            Some(egui::vec2(0.0, 119.0)),
        );
        assert_eq!(
            app.secondary_scroll_accum.get(&monitor_b).copied(),
            Some(egui::vec2(0.0, 50.0)),
        );
    }

    #[test]
    fn close_multi_window_session_clears_every_secondary_scroll_accumulator() {
        // "Cleanup on session teardown": a stale monitor id's leftover
        // scroll remainder from a prior committed roster must never linger
        // into a later one (a fresh topology could reuse the same
        // negotiated `SessionMonitorId` for a physically different
        // monitor).
        let mut app = ArcenApp::default();
        app.secondary_scroll_accum.insert(
            arcen_media::SessionMonitorId::new(2).expect("valid id"),
            egui::vec2(0.0, 90.0),
        );

        app.close_multi_window_session();

        assert!(
            app.secondary_scroll_accum.is_empty(),
            "a torn-down multi-window session must clear every secondary's own scroll \
             accumulator",
        );
    }

    #[test]
    fn close_multi_window_session_resets_root_scroll_accum_and_every_secondary_pointer_lock_state()
    {
        // Item 3 (enablement audit): teardown must reset root's own
        // scroll accumulator too, plus any lingering secondary pointer
        // lock ownership/relative-motion accumulator state -- none of it
        // may survive into whatever comes next.
        let mut app = ArcenApp::default();
        app.root_scroll_accum = egui::vec2(0.0, 77.0);
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        app.secondary_pointer_lock = Some(monitor_id);
        app.secondary_relative_motion
            .insert(monitor_id, FractionalMotionAccumulator::default());

        app.close_multi_window_session();

        assert_eq!(
            app.root_scroll_accum,
            egui::Vec2::ZERO,
            "root's own scroll accumulator must never leak a sub-tick remainder past teardown",
        );
        assert!(
            app.secondary_pointer_lock.is_none(),
            "a torn-down session must never leave a secondary holding the pointer lock",
        );
        assert!(
            app.secondary_relative_motion.is_empty(),
            "a torn-down session must clear every secondary's own relative-motion accumulator",
        );
    }

    #[test]
    fn install_session_handle_resets_root_scroll_accum_on_launch_reconnect_and_new_attach() {
        // Item 3 (enablement audit): `install_session_handle` is the
        // single chokepoint every fresh connect ("launch") and every
        // resume ("reconnect/new attach") both funnel through -- a
        // leftover scroll remainder from whatever came before must never
        // survive into the freshly (re)installed session.
        let mut app = ArcenApp::default();
        app.root_scroll_accum = egui::vec2(0.0, 42.0);
        let (_media_tx, media) = crate::pipeline::frame_queue::incoming_media_inbox();
        let (events_tx, events) = mpsc::unbounded_channel();
        // Dropped immediately: the worker thread's very first receive then
        // observes a closed channel and exits right away, with no live
        // sender left for it to ever block on.
        drop(events_tx);
        let (commands_tx, _commands_rx) = mpsc::unbounded_channel();
        let commands = SessionCommandSender::for_test(commands_tx);
        let clipboard = crate::clipboard::ClipboardSession::new();
        let handle = crate::transport::websocket::SessionHandle {
            events,
            media,
            commands,
            clipboard,
        };
        let ctx = egui::Context::default();

        app.install_session_handle(handle, false, &ctx);

        assert_eq!(
            app.root_scroll_accum,
            egui::Vec2::ZERO,
            "a fresh session attach must reset root's own scroll accumulator",
        );
    }

    #[test]
    fn drive_multi_window_releases_stale_root_pointer_lock_when_a_secondary_is_focused() {
        // Needs 2 distinct live displays: an unresolvable target is forced
        // to `focused: false` unconditionally (the `Err` branch in
        // `drive_multi_window`'s per-assignment loop never runs this
        // viewport's own closure at all), which could never exercise this
        // release path -- see `drive_multi_window_stays_pending_...`'s own
        // doc for the same requirement.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.len() < 2 {
            eprintln!(
                "skipping: need at least 2 live active displays in this environment to reach a \
                 genuinely resolved (non-hard-failing) secondary viewport",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        let secondary_display_id = live_display_ids[1];
        let (mut app, mut receiver) = app_with_command_channel();
        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(2)
                            .expect("valid id"),
                        cg_display_id: secondary_display_id,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1, 2]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3840,
                    height_px: 1080,
                },
            }
        };
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        app.multi_window = MultiWindowSessionState::Active {
            validated: validated.clone(),
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: true,
        };
        app.multi_window_started_at = Some(Instant::now());
        assert!(app.ensure_region_runtime_for_validated(&validated));
        let primary_viewport = app
            .region_runtime
            .as_ref()
            .expect("region runtime")
            .primary_viewport();
        app.dispatch_region_pointer_sample(
            primary_viewport,
            (0.5, 0.5),
            &[(1, true)],
            PointerMotionMode::Absolute,
        );
        while receiver.try_recv().is_ok() {}
        app.pointer_lock = true;

        // Drive one real egui pass (not just a bare, never-run `Context`)
        // with `focused: true` so this pass's ambient `InputState.focused`
        // -- which the embedded-viewport fallback every secondary's
        // closure reads via `ui.input(|i| i.focused)` shares with root's
        // own pass under this test harness (no native
        // `IMMEDIATE_VIEWPORT_RENDERER` is registered) -- is genuinely
        // `true`, exercising the real per-frame wiring end to end rather
        // than only the extracted pure helper/wrapper in isolation.
        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            focused: true,
            ..egui::RawInput::default()
        });
        app.drive_multi_window(&ctx);
        let _ = ctx.end_pass();

        assert!(
            !app.pointer_lock,
            "OS focus reported on a secondary this frame must force root's stale pointer lock \
             off via the real drive_multi_window wiring",
        );
        assert_eq!(app.remote_pointer_buttons, [false; 3]);
        let release_msg = receive_region_json(&mut receiver, "region_pointer_button");
        assert_eq!(release_msg["pressed"], false);

        // Secondary dispatch must no longer be suppressed by the
        // now-cleared lock.
        app.dispatch_secondary_pointer(
            &validated,
            monitor_id,
            (0.5, 0.5),
            [(1, true), (2, false), (3, false)],
        );
        let button_msg = receive_region_json(&mut receiver, "region_pointer_button");
        assert_eq!(button_msg["pressed"], true);

        // Focus "returning to root" (no secondary reporting focus this
        // frame) must never silently re-acquire the lock.
        let ctx2 = egui::Context::default();
        ctx2.begin_pass(egui::RawInput {
            focused: false,
            ..egui::RawInput::default()
        });
        app.drive_multi_window(&ctx2);
        let _ = ctx2.end_pass();
        assert!(
            !app.pointer_lock,
            "pointer lock must stay off once released -- it is an explicit user toggle only",
        );
    }

    #[test]
    fn drive_multi_window_releases_held_keys_before_dispatching_a_newly_focused_secondarys_own_key_event_root_to_secondary(
    ) {
        // Ultimate audit finding #2: a root -> secondary focus change
        // observed within a single `drive_multi_window` call must
        // reconcile focus (releasing every key held against root) via
        // `sync_keyboard_focus_across_viewports` *before* this same call
        // dispatches the winning secondary's own keyboard events -- never
        // after, which would let the new viewport's first keydown race
        // ahead of root's held-key release.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.len() < 2 {
            eprintln!(
                "skipping: need at least 2 live active displays in this environment to reach a \
                 genuinely resolved (non-hard-failing) secondary viewport whose closure actually \
                 runs and reports focus/keyboard events",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        let secondary_display_id = live_display_ids[1];
        let (mut app, mut receiver) = app_with_command_channel();
        // Simulate the previous frame's `ui()` call having already
        // resolved root as the focused viewport, with a modifier + key
        // physically held against it.
        app.active_keyboard_viewport = Some(FocusedKeyboardViewport::Root);
        seed_non_modifier_and_modifier(&mut app, &mut receiver);

        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: monitor_id,
                        cg_display_id: secondary_display_id,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3840,
                    height_px: 1080,
                },
            }
        };
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: true,
        };
        app.multi_window_started_at = Some(Instant::now());

        // Drive one real pass reporting OS focus on the (only resolvable)
        // secondary, with a brand-new key event queued for it -- exactly
        // what the embedded-viewport fallback (no native
        // `IMMEDIATE_VIEWPORT_RENDERER` registered under this test
        // harness) hands every viewport's own `ui.input()` this pass, see
        // `drive_multi_window_releases_stale_root_pointer_lock_when_a_secondary_is_focused`'s
        // own doc for the same mechanic.
        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            focused: true,
            events: vec![key_event(egui::Key::C, true, egui::Modifiers::NONE)],
            ..egui::RawInput::default()
        });
        app.drive_multi_window(&ctx);
        let _ = ctx.end_pass();

        // Root's held Shift+A must be released, and the reset sent, before
        // the new secondary's own "C" keydown is ever forwarded.
        assert_releases_before_reset(&mut receiver, "viewport_switch");
        let new_key_msg = receive_json(&mut receiver);
        assert_eq!(new_key_msg["type"], "key_event");
        assert_eq!(new_key_msg["pressed"], true);

        assert_eq!(
            app.active_keyboard_viewport,
            Some(FocusedKeyboardViewport::Secondary(monitor_id))
        );
        assert_eq!(app.active_secondary_keyboard_focus, Some(monitor_id));
        // Only "C" (the secondary's own fresh event) remains held -- the
        // root modifier/key pair was fully released, not carried forward.
        assert_eq!(app.keyboard.held_count(), 1);
    }

    #[test]
    fn drive_multi_window_releases_held_keys_before_dispatching_a_newly_focused_secondarys_own_key_event_secondary_to_secondary(
    ) {
        // Same finding as above, but for a secondary -> a *different*
        // secondary focus change within one `drive_multi_window` call:
        // the combined "some viewport of ours is focused" signal never
        // drops to `false` in between (unlike a root -> secondary
        // change), so this exercises `sync_keyboard_focus_across_viewports`'s
        // own "internal switch" detection specifically, still strictly
        // before the new viewport's key event is dispatched.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.len() < 2 {
            eprintln!(
                "skipping: need at least 2 live active displays in this environment to reach a \
                 genuinely resolved (non-hard-failing) secondary viewport whose closure actually \
                 runs and reports focus/keyboard events",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        let secondary_display_id = live_display_ids[1];
        let (mut app, mut receiver) = app_with_command_channel();
        // A *different*, no-longer-assigned secondary held focus (and a
        // held modifier + key) a moment ago.
        let previous_monitor_id = arcen_media::SessionMonitorId::new(9).expect("valid id");
        app.active_keyboard_viewport =
            Some(FocusedKeyboardViewport::Secondary(previous_monitor_id));
        seed_non_modifier_and_modifier(&mut app, &mut receiver);

        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: monitor_id,
                        cg_display_id: secondary_display_id,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3840,
                    height_px: 1080,
                },
            }
        };
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: true,
        };
        app.multi_window_started_at = Some(Instant::now());

        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            focused: true,
            events: vec![key_event(egui::Key::D, true, egui::Modifiers::NONE)],
            ..egui::RawInput::default()
        });
        app.drive_multi_window(&ctx);
        let _ = ctx.end_pass();

        assert_releases_before_reset(&mut receiver, "viewport_switch");
        let new_key_msg = receive_json(&mut receiver);
        assert_eq!(new_key_msg["type"], "key_event");
        assert_eq!(new_key_msg["pressed"], true);

        assert_eq!(
            app.active_keyboard_viewport,
            Some(FocusedKeyboardViewport::Secondary(monitor_id))
        );
        assert_eq!(app.active_secondary_keyboard_focus, Some(monitor_id));
        assert_eq!(app.keyboard.held_count(), 1);
        // The session as a whole never dropped keyboard focus in between --
        // an internal secondary -> secondary switch, not a real focus loss.
        assert!(app.keyboard.focused());
    }

    #[test]
    fn drive_multi_window_dispatches_keyboard_events_only_from_the_focus_winner_when_two_secondaries_are_simultaneously_focused(
    ) {
        // Gate-readiness finding #2: once one active secondary keyboard-
        // focus *winner* is selected for the frame (`.find`'s first match
        // over `results`, mirroring exactly what
        // `active_secondary_keyboard_focus` itself is set to), the
        // dispatch loop below must forward `keyboard_events` from that
        // exact winning viewport alone -- a second, transiently
        // simultaneously-focused secondary (an artifact this embedded test
        // harness reproduces directly, since every viewport shares the same
        // single top-level `RawInput::focused`/`events` this pass, just as
        // two real native windows can transiently both still report OS
        // focus mid-switch) must never have its own copy of the same event
        // dispatched a second time.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.len() < 3 {
            eprintln!(
                "skipping: need at least 3 live active displays in this environment (root + two \
                 secondaries) to reach two genuinely resolved (non-hard-failing) secondary \
                 viewports whose closures actually run and both report focus/keyboard events",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        let secondary_a_display_id = live_display_ids[1];
        let secondary_b_display_id = live_display_ids[2];
        let (mut app, mut receiver) = app_with_command_channel();
        app.active_keyboard_viewport = None;

        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: monitor_a,
                        cg_display_id: secondary_a_display_id,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: monitor_b,
                        cg_display_id: secondary_b_display_id,
                        rect: MonitorDesktopRect {
                            x: 3840,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 5760,
                    height_px: 1080,
                },
            }
        };
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: true,
        };
        app.multi_window_started_at = Some(Instant::now());

        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            focused: true,
            events: vec![key_event(egui::Key::D, true, egui::Modifiers::NONE)],
            ..egui::RawInput::default()
        });
        app.drive_multi_window(&ctx);
        let _ = ctx.end_pass();

        // Exactly one copy of the shared key event was dispatched -- from
        // the resolved winner alone -- never twice, even though this
        // harness makes both secondaries equally report `focused: true`
        // this same pass.
        let key_msg = receive_json(&mut receiver);
        assert_eq!(key_msg["type"], "key_event");
        assert_eq!(key_msg["pressed"], true);
        assert!(
            receiver.try_recv().is_err(),
            "the transiently co-focused loser's own copy of the same event must never be \
             dispatched a second time",
        );

        // The winner is whichever resolved secondary result was found
        // first (`monitor_a`, `results`' own iteration order over
        // `assignments`, which itself always keeps the negotiated roster's
        // relative order) -- and `active_keyboard_viewport` is reconciled
        // to that exact same winner, never left ambiguous between the two.
        assert_eq!(app.active_secondary_keyboard_focus, Some(monitor_a));
        assert_eq!(
            app.active_keyboard_viewport,
            Some(FocusedKeyboardViewport::Secondary(monitor_a))
        );
        assert_eq!(app.keyboard.held_count(), 1);
    }

    #[test]
    fn resolve_secondary_keyboard_focus_winner_picks_the_first_focused_entry_when_two_report_focus()
    {
        // Hardware-independent complement to
        // `drive_multi_window_dispatches_keyboard_events_only_from_the_focus_winner_when_two_secondaries_are_simultaneously_focused`:
        // exercises the exact same winner-selection pure function directly
        // against synthetic focus flags, so this specific semantics is
        // verified even in environments (like this one) with too few real
        // displays to drive the full viewport loop.
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");

        let winner =
            resolve_secondary_keyboard_focus_winner([(monitor_a, true), (monitor_b, true)]);
        assert_eq!(
            winner,
            Some(monitor_a),
            "the first entry reporting focus is the winner, even when a second entry \
             simultaneously also reports focus",
        );
    }

    #[test]
    fn resolve_secondary_keyboard_focus_winner_is_none_when_nothing_is_focused() {
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");

        assert_eq!(
            resolve_secondary_keyboard_focus_winner([(monitor_a, false), (monitor_b, false)]),
            None,
        );
    }

    #[test]
    fn resolve_secondary_keyboard_focus_winner_skips_unfocused_entries_before_the_actual_winner() {
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");

        assert_eq!(
            resolve_secondary_keyboard_focus_winner([(monitor_a, false), (monitor_b, true)]),
            Some(monitor_b),
        );
    }

    #[test]
    fn should_dispatch_secondary_keyboard_events_is_true_only_for_the_exact_winner() {
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_b = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let winner = Some(monitor_a);

        assert!(
            should_dispatch_secondary_keyboard_events(monitor_a, winner),
            "the resolved winner's own events must be dispatched",
        );
        assert!(
            !should_dispatch_secondary_keyboard_events(monitor_b, winner),
            "a different, non-winning viewport's events -- even one that itself also \
             transiently reported focus this frame -- must never be dispatched",
        );
    }

    #[test]
    fn should_dispatch_secondary_keyboard_events_is_false_for_every_viewport_when_there_is_no_winner(
    ) {
        let monitor_a = arcen_media::SessionMonitorId::new(2).expect("valid id");
        assert!(!should_dispatch_secondary_keyboard_events(monitor_a, None));
    }

    #[test]
    fn resolve_tablet_sample_target_matches_root_by_window_number() {
        let root_view = ViewSize::new(1920.0, 1080.0);
        let secondary_view = ViewSize::new(1920.0, 1080.0);
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let secondary_targets = vec![(42_isize, monitor_id, secondary_view)];

        let resolved = resolve_tablet_sample_target(7, Some(7), root_view, &secondary_targets)
            .expect("root's own window number must resolve to root");

        assert_eq!(resolved.1, None, "root path carries no monitor id");
    }

    #[test]
    fn resolve_tablet_sample_target_matches_a_committed_secondary_window() {
        let root_view = ViewSize::new(1920.0, 1080.0);
        let secondary_view = ViewSize::new(1440.0, 2560.0);
        let monitor_id = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let secondary_targets = vec![(42_isize, monitor_id, secondary_view)];

        let (view, resolved_monitor_id) =
            resolve_tablet_sample_target(42, Some(7), root_view, &secondary_targets)
                .expect("a window number present in secondary_targets must resolve");

        assert_eq!(resolved_monitor_id, Some(monitor_id));
        // The rotated secondary's own `ViewSize` must be what is returned,
        // never root's -- comparing debug output since `ViewSize` has no
        // public field accessors (by design: only `within_window`/`new`
        // construct one).
        assert_eq!(format!("{view:?}"), format!("{secondary_view:?}"));
    }

    #[test]
    fn resolve_tablet_sample_target_drops_a_window_matching_neither_root_nor_any_secondary() {
        let root_view = ViewSize::new(1920.0, 1080.0);
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let secondary_targets = vec![(42_isize, monitor_id, ViewSize::new(1920.0, 1080.0))];

        // Neither root's window number (7) nor the one committed secondary
        // (42) -- e.g. a stray/foreign window, or a stale sample from a
        // viewport that already closed this frame.
        let resolved = resolve_tablet_sample_target(999, Some(7), root_view, &secondary_targets);

        assert!(
            resolved.is_none(),
            "an ambiguous window must be dropped, never default to root"
        );
    }

    #[test]
    fn resolve_tablet_sample_target_disambiguates_multiple_secondaries_by_window_number() {
        let root_view = ViewSize::new(1920.0, 1080.0);
        let monitor_b = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let monitor_c = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let view_b = ViewSize::new(1920.0, 1080.0);
        // A rotated third monitor: distinctly different dimensions from
        // both root and monitor_b so a mismatch cannot go unnoticed.
        let view_c = ViewSize::new(1440.0, 2560.0);
        let secondary_targets = vec![(10_isize, monitor_b, view_b), (11_isize, monitor_c, view_c)];

        let (_, resolved_b) =
            resolve_tablet_sample_target(10, Some(7), root_view, &secondary_targets).unwrap();
        let (_, resolved_c) =
            resolve_tablet_sample_target(11, Some(7), root_view, &secondary_targets).unwrap();

        assert_eq!(resolved_b, Some(monitor_b));
        assert_eq!(resolved_c, Some(monitor_c));
    }

    #[test]
    fn tablet_sample_forward_allowed_root_samples_are_never_gated_by_commit_state() {
        assert!(tablet_sample_forward_allowed(None, false));
        assert!(tablet_sample_forward_allowed(None, true));
    }

    #[test]
    fn tablet_sample_forward_allowed_secondary_samples_are_dropped_until_committed() {
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        assert!(!tablet_sample_forward_allowed(Some(monitor_id), false));
        assert!(tablet_sample_forward_allowed(Some(monitor_id), true));
    }

    #[test]
    fn pre_commit_pen_sample_on_a_secondary_viewport_is_dropped_not_misrouted_to_root() {
        // Mirrors `process_tablet_samples`'s own two-stage per-sample
        // routing: the native window genuinely matches a secondary
        // viewport's own window number (so `resolve_tablet_sample_target`
        // correctly identifies it -- never counted as `dropped_ambiguous`),
        // but that viewport's multi-window transaction has not committed
        // yet. Finding #1's requirement: such a sample must still be
        // unavailable, exactly like secondary mouse/keyboard input's own
        // `self.multi_window.is_committed()` gate, and dropped outright
        // rather than ever falling back through root's own rect.
        let root_view = ViewSize::new(1920.0, 1080.0);
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let secondary_view = ViewSize::new(1920.0, 1080.0);
        let secondary_targets = vec![(10_isize, monitor_id, secondary_view)];

        let (view, resolved_monitor_id) =
            resolve_tablet_sample_target(10, Some(7), root_view, &secondary_targets)
                .expect("window number genuinely matches the open secondary viewport");
        assert_eq!(resolved_monitor_id, Some(monitor_id));
        assert_eq!(format!("{view:?}"), format!("{secondary_view:?}"));

        // Not committed yet: this sample must be dropped, never forwarded
        // through root and never sent for the secondary either.
        assert!(
            !tablet_sample_forward_allowed(resolved_monitor_id, false),
            "a secondary-resolved sample must be unavailable before commit"
        );

        // Once the transaction commits, the exact same resolved sample is
        // now allowed through.
        assert!(tablet_sample_forward_allowed(resolved_monitor_id, true));

        // Root's own samples from the very same frame are entirely
        // unaffected by commit state either way.
        let (_, root_monitor_id) =
            resolve_tablet_sample_target(7, Some(7), root_view, &secondary_targets)
                .expect("root's own window number always resolves");
        assert!(root_monitor_id.is_none());
        assert!(tablet_sample_forward_allowed(root_monitor_id, false));
        assert!(tablet_sample_forward_allowed(root_monitor_id, true));
    }

    #[test]
    fn tablet_root_fallback_allowed_only_when_no_multi_window_attempt_exists() {
        assert!(tablet_root_fallback_allowed(false));
        assert!(!tablet_root_fallback_allowed(true));
    }

    #[test]
    fn just_opened_secondarys_unresolved_window_number_is_dropped_not_misrouted_to_root_pre_commit()
    {
        // Audit finding: the root fallback must key off "does a
        // multi-window attempt exist at all" (pending or committed), never
        // off `secondary_tablet_targets.is_empty()` -- that vector can
        // legitimately still be empty for a frame or more right after a
        // multi-window attempt begins, e.g. a just-opened secondary
        // viewport whose own window number `drive_multi_window` has not
        // yet resolved into an entry. A sample carrying that secondary's
        // real native window number must never bypass through the root
        // fallback just because the targets table happens to be empty (or
        // simply doesn't yet contain a matching entry) this frame -- it
        // must be positively resolved and, being unmatched, dropped as
        // ambiguous.
        let multi_window_attempt_active = true;
        let root_window_number = Some(7_isize);
        let root_view = ViewSize::new(1920.0, 1080.0);
        let just_opened_secondary_window_number = 42_isize;

        assert!(!tablet_root_fallback_allowed(multi_window_attempt_active));

        // Empty table: the just-opened secondary has no entry yet.
        let empty_targets: Vec<(isize, arcen_media::SessionMonitorId, ViewSize)> = Vec::new();
        let resolved = resolve_tablet_sample_target(
            just_opened_secondary_window_number,
            root_window_number,
            root_view,
            &empty_targets,
        );
        assert!(
            resolved.is_none(),
            "an unresolved secondary window must be dropped as ambiguous, never fall back to root"
        );

        // A populated table that simply doesn't (yet) contain this
        // particular window number -- e.g. a *different* secondary already
        // resolved, but not this one -- must drop it identically, never
        // treat "table nonempty" as license to fall back to root either.
        let other_monitor_id = arcen_media::SessionMonitorId::new(3).expect("valid id");
        let nonmatching_targets = vec![(99_isize, other_monitor_id, root_view)];
        let resolved = resolve_tablet_sample_target(
            just_opened_secondary_window_number,
            root_window_number,
            root_view,
            &nonmatching_targets,
        );
        assert!(
            resolved.is_none(),
            "a window number matching no committed secondary must be dropped, not misrouted"
        );
    }

    #[test]
    fn once_the_secondarys_own_entry_resolves_its_samples_route_and_forward_after_commit() {
        // Same scenario a frame or two later: `secondary_tablet_targets`
        // now carries the previously-unresolved secondary's own entry.
        // Proves the earlier drop was purely a transient pre-resolution
        // state, not a permanent misrouting -- and that forwarding still
        // separately requires commit (Finding #1's own gate), never
        // implied merely by having resolved a target.
        let root_window_number = Some(7_isize);
        let root_view = ViewSize::new(1920.0, 1080.0);
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        let secondary_view = ViewSize::new(1920.0, 1080.0);
        let secondary_targets = vec![(42_isize, monitor_id, secondary_view)];
        let window_number = 42_isize;

        let (_, resolved_monitor_id) = resolve_tablet_sample_target(
            window_number,
            root_window_number,
            root_view,
            &secondary_targets,
        )
        .expect("now resolved to the committed secondary's own entry");
        assert_eq!(resolved_monitor_id, Some(monitor_id));

        assert!(!tablet_sample_forward_allowed(resolved_monitor_id, false));
        assert!(tablet_sample_forward_allowed(resolved_monitor_id, true));
    }

    #[test]
    fn pen_sample_on_a_rotated_secondary_viewport_uses_direct_region_input() {
        let validated = two_monitor_validated_topology_with_rotated_secondary();
        let monitor_id = arcen_media::SessionMonitorId::new(2).expect("valid id");
        // The rotated secondary's own content rect is 1440x2560 (portrait).
        let secondary_view = ViewSize::new(1440.0, 2560.0);
        let mut mapper = TabletMapper::new();
        let metadata = arcen_input::LowLatencyMetadata {
            sequence: 1,
            timestamp_ns: 1,
            coalescable: true,
        };
        // Bottom-right corner in AppKit's bottom-left-origin space is
        // `(window_width, 0)`.
        let sample = crate::tablet::NativeTabletPoint {
            window_x: 1440.0,
            window_y: 0.0,
            pressure: 0.6,
            tilt_x: 0.0,
            tilt_y: 0.0,
            rotation_degrees: 0.0,
            buttons: crate::tablet::TabletButtonMask::new(0),
            device_id: 1,
            tool: crate::tablet::NativeTabletTool::Eraser,
            window_number: 42,
        };

        let event = mapper
            .on_point(sample, secondary_view, metadata)
            .expect("a syntactically valid sample must map");
        assert_eq!(event.tool, PenTool::Eraser);

        let (mut app, mut receiver) = app_with_command_channel();
        assert!(app.ensure_region_runtime_for_validated(&validated));
        app.remote_frame_size = Some([1920, 1080]);
        let viewport = app
            .region_runtime
            .as_ref()
            .and_then(|runtime| runtime.viewport_for_monitor(monitor_id))
            .expect("secondary region viewport");

        app.send_region_pen_event(event, viewport);

        let message = receive_json(&mut receiver);
        assert_eq!(message["type"], "region_pen_event");
        assert_eq!(message["region_id"], 2);
        assert_eq!(message["logical_x"], 1440 * 120 - 1);
        assert_eq!(message["logical_y"], 2560 * 120 - 1);
        assert_eq!(message["tool"], "eraser");
        assert_direct_region_json(&message);
    }

    #[test]
    fn drive_root_multi_window_target_only_sends_set_monitor_when_the_caller_says_it_is_needed() {
        // "Avoid sending SetMonitor every frame; track requested target" --
        // this proves it at the exact call boundary that issues the
        // command: `drive_root_multi_window_target` itself must honor
        // `move_command_needed` rather than deciding on its own, every
        // single frame, purely from "is root currently on the wrong
        // display".
        let ctx = egui::Context::default();
        let active_display_ids = [42_u32, 100];

        // Under this bare test context no real native window is open, so
        // `window_display_id` fails closed to `None` -- root's observed
        // display id is always `None`, which never equals `Some(42)`,
        // exactly mirroring root's real pre-move state (on some other, or
        // no yet resolvable, display).
        let (_, sent_first, _) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, true, true);
        assert!(
            sent_first,
            "a caller-confirmed-needed command must actually be sent the first time",
        );

        let (_, sent_while_not_needed, _) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, false, false);
        assert!(
            !sent_while_not_needed,
            "must not resend SetMonitor every frame once the caller says it is not needed, \
             even though root is still observed on the wrong (unresolvable) display",
        );

        // Once the caller decides a (re)send is needed again (e.g. a
        // renegotiated primary), it must be sent again.
        let (_, sent_again, _) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, true, false);
        assert!(
            sent_again,
            "a fresh caller-confirmed-needed request must send the command again",
        );
    }

    #[test]
    fn drive_root_multi_window_target_sends_no_command_when_the_target_display_is_not_resolvable() {
        // A target that has already disappeared from the live list must
        // never be sent at all -- there is no valid monitor index to give
        // `SetMonitor`. The caller's own `record_observation`/
        // `target_still_active` path (fed the same active display list) is
        // what latches `DisplayDisappeared` through the normal path
        // instead.
        let ctx = egui::Context::default();
        let active_display_ids = [100_u32];

        let (_, sent, snapshot) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, true, true);
        assert!(
            !sent,
            "an unresolvable target display must never be sent to SetMonitor",
        );
        assert!(
            snapshot.is_none(),
            "no command sent must mean no snapshot captured either",
        );
    }

    #[test]
    fn drive_root_multi_window_target_sends_a_command_for_a_same_display_windowed_start() {
        // Item 1: root already resident on the negotiated primary display
        // but not yet fullscreen must still get a `SetMonitor` once (which
        // both re-affirms the monitor and requests fullscreen) -- the old
        // display-only condition never fired here, since `observed ==
        // expected` already held, and root would simply wait forever,
        // never confirming.
        let ctx = egui::Context::default();
        let active_display_ids = [42_u32];

        // Under the bare test context, `window_display_id` always fails
        // closed to `None`, so this cannot literally simulate "observed ==
        // expected" -- but it does simulate "not yet fullscreen"
        // (`info.fullscreen` defaults to `None`, which is not
        // `Some(true)`), and the fullscreen half of the OR condition is
        // exactly what this test is proving actually exists: without it,
        // this scenario would rely purely on the (here, artificially
        // untestable) display mismatch to trigger the first send.
        let (observation, sent, snapshot) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, true, true);
        assert!(
            observation.fullscreen != Some(true),
            "sanity: the bare test context never reports genuine fullscreen",
        );
        assert!(
            sent,
            "a not-yet-fullscreen root must receive SetMonitor even when \
             already on the right display",
        );
        assert!(
            snapshot.is_some(),
            "the first command this attempt ever sends must capture a pre-entry snapshot",
        );

        // Once sent, the caller's own `root_move_command_needed` gating
        // (simulated here directly via `move_command_needed = false`) must
        // prevent a resend every frame while fullscreen confirmation is
        // still pending -- exactly the "avoid repeated commands" half of
        // this fix.
        let (_, resent, resnapshot) =
            drive_root_multi_window_target(&ctx, 42, &active_display_ids, false, false);
        assert!(
            !resent,
            "must not resend while the caller says no fresh command is needed, \
             even though fullscreen still is not confirmed",
        );
        assert!(resnapshot.is_none());
    }

    // ---------------------------------------------------------------
    // Root entry transaction: pre-entry snapshot capture and restore
    // (`RootPreEntrySnapshot`). These prove `restore_commands` in
    // isolation -- pure logic, given a synthetic `active_display_ids`
    // slice, no real hardware dependency -- then the `ArcenApp`-level
    // wiring (`close_multi_window_session` -> `pending_root_restore` ->
    // `drain_pending_root_restore`), then one end-to-end
    // `drive_multi_window` scenario gated on this environment actually
    // having a real live display (needed for root's own move command to
    // ever fire and a snapshot to actually be captured).
    // ---------------------------------------------------------------

    #[test]
    fn root_pre_entry_snapshot_restore_commands_resolves_the_original_display_and_restores_windowed(
    ) {
        let snapshot = RootPreEntrySnapshot {
            display_id: Some(100),
            fullscreen: Some(false),
            inner_rect_size_pts: Some((1120.0, 792.0)),
        };
        let active_display_ids = [200_u32, 100, 300];
        let (monitor_index, restore_fullscreen) = snapshot.restore_commands(&active_display_ids);
        assert_eq!(
            monitor_index,
            Some(1),
            "must resolve the original display's live index (not a stale one captured at \
             snapshot time)",
        );
        assert!(
            !restore_fullscreen,
            "a windowed original must restore to windowed",
        );
    }

    #[test]
    fn root_pre_entry_snapshot_restore_commands_restores_fullscreen_when_originally_fullscreen() {
        // "original fullscreen remains fullscreen" -- root that was
        // already fullscreen on some display before the multi-window
        // attempt ever touched it must be restored back to fullscreen,
        // never dropped to windowed.
        let snapshot = RootPreEntrySnapshot {
            display_id: Some(100),
            fullscreen: Some(true),
            inner_rect_size_pts: None,
        };
        let active_display_ids = [100_u32];
        let (monitor_index, restore_fullscreen) = snapshot.restore_commands(&active_display_ids);
        assert_eq!(monitor_index, Some(0));
        assert!(
            restore_fullscreen,
            "an originally-fullscreen root must be restored to fullscreen",
        );
    }

    #[test]
    fn root_pre_entry_snapshot_restore_commands_defaults_to_windowed_when_fullscreen_state_was_unknown(
    ) {
        let snapshot = RootPreEntrySnapshot {
            display_id: Some(100),
            fullscreen: None,
            inner_rect_size_pts: None,
        };
        let (_, restore_fullscreen) = snapshot.restore_commands(&[100]);
        assert!(
            !restore_fullscreen,
            "an unknown prior fullscreen state must default to the safe windowed restore",
        );
    }

    #[test]
    fn root_pre_entry_snapshot_restore_commands_yields_no_monitor_index_when_original_display_is_gone(
    ) {
        let snapshot = RootPreEntrySnapshot {
            display_id: Some(100),
            fullscreen: Some(false),
            inner_rect_size_pts: None,
        };
        let (monitor_index, _) = snapshot.restore_commands(&[200, 300]);
        assert_eq!(
            monitor_index, None,
            "a display that has disappeared must never be sent to SetMonitor",
        );
    }

    #[test]
    fn close_multi_window_session_moves_an_uncommitted_root_snapshot_into_pending_restore() {
        let mut app = ArcenApp::default();
        let snapshot = RootPreEntrySnapshot {
            display_id: Some(42),
            fullscreen: Some(false),
            inner_rect_size_pts: None,
        };
        app.root_pre_entry_snapshot = Some(snapshot);

        app.close_multi_window_session();

        assert_eq!(
            app.pending_root_restore,
            Some(snapshot),
            "a precommit teardown must move the snapshot into pending_root_restore verbatim",
        );
        assert!(
            app.root_pre_entry_snapshot.is_none(),
            "the source field must be drained, not merely copied",
        );
    }

    #[test]
    fn close_multi_window_session_leaves_pending_restore_none_when_no_snapshot_was_ever_captured() {
        // The "no command/no snapshot" case: root never needed to move
        // (already resident on the negotiated primary), so
        // `root_pre_entry_snapshot` was never populated in the first
        // place -- teardown must not invent a restore out of nothing.
        let mut app = ArcenApp::default();
        assert!(app.root_pre_entry_snapshot.is_none());

        app.close_multi_window_session();

        assert!(
            app.pending_root_restore.is_none(),
            "no snapshot ever captured must mean no restore is ever queued",
        );
    }

    #[test]
    fn close_multi_window_session_does_not_restore_after_a_commit_already_cleared_the_snapshot() {
        // On commit hand off to normal session fullscreen restore policy
        // without double restore: once `commit_multi_window_entry` has
        // cleared `root_pre_entry_snapshot` (as it always does on a real
        // commit), a *later* teardown of that same, now-committed session
        // must find nothing left to restore.
        let mut app = ArcenApp::default();
        app.root_pre_entry_snapshot = Some(RootPreEntrySnapshot {
            display_id: Some(42),
            fullscreen: Some(false),
            inner_rect_size_pts: None,
        });
        app.commit_multi_window_entry();
        assert!(app.root_pre_entry_snapshot.is_none());

        app.close_multi_window_session();

        assert!(
            app.pending_root_restore.is_none(),
            "a post-commit teardown must never restore root -- the normal \
             session_fullscreen_restore policy already owns this",
        );
    }

    #[test]
    fn close_multi_window_session_called_twice_for_the_same_teardown_does_not_clobber_the_pending_restore(
    ) {
        // `multi_window_failure` can legitimately call `drop_session_handles`
        // (and so this method) twice for one failure: once directly, then
        // again from `return_to_credentials`'s own `drop_session_handles`
        // when no reconnect gets scheduled. Every other reset this method
        // performs is naturally idempotent; `pending_root_restore` must be
        // too -- a second, already-empty call must never overwrite what the
        // first call just queued back to `None`.
        let mut app = ArcenApp::default();
        app.root_pre_entry_snapshot = Some(RootPreEntrySnapshot {
            display_id: Some(7),
            fullscreen: Some(true),
            inner_rect_size_pts: Some((1920.0, 1080.0)),
        });

        app.close_multi_window_session();
        assert_eq!(
            app.pending_root_restore.as_ref().and_then(|s| s.display_id),
            Some(7),
            "the first call must queue the snapshot for restore",
        );

        app.close_multi_window_session();
        assert_eq!(
            app.pending_root_restore.as_ref().and_then(|s| s.display_id),
            Some(7),
            "a second call with nothing left to take must leave the already-queued \
             restore untouched, not clobber it back to None",
        );
    }

    #[test]
    fn commit_multi_window_entry_flips_committed_and_clears_the_snapshot() {
        let validated = single_monitor_validated_topology();
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp::default();
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.root_pre_entry_snapshot = Some(RootPreEntrySnapshot {
            display_id: Some(7),
            fullscreen: Some(true),
            inner_rect_size_pts: None,
        });

        app.commit_multi_window_entry();

        assert!(matches!(
            app.multi_window,
            MultiWindowSessionState::Active {
                committed: true,
                ..
            }
        ));
        assert!(
            app.root_pre_entry_snapshot.is_none(),
            "a commit must clear the snapshot without restoring it",
        );
    }

    #[test]
    fn drain_pending_root_restore_is_a_noop_when_nothing_is_pending() {
        let mut app = ArcenApp::default();
        let ctx = egui::Context::default();
        assert!(app.pending_root_restore.is_none());

        app.drain_pending_root_restore(&ctx);

        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        assert!(
            sent.is_empty(),
            "nothing pending must mean no restore commands are ever sent",
        );
    }

    #[test]
    fn drain_pending_root_restore_sends_fullscreen_restore_and_clears_the_pending_snapshot() {
        let mut app = ArcenApp::default();
        let ctx = egui::Context::default();
        app.pending_root_restore = Some(RootPreEntrySnapshot {
            display_id: None,
            fullscreen: Some(false),
            inner_rect_size_pts: None,
        });

        app.drain_pending_root_restore(&ctx);

        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        assert!(
            sent.contains(&egui::ViewportCommand::Fullscreen(false)),
            "must restore windowed mode: {sent:?}",
        );
        assert!(
            !sent
                .iter()
                .any(|command| matches!(command, egui::ViewportCommand::SetMonitor(_))),
            "no display id to resolve must mean no SetMonitor is ever sent: {sent:?}",
        );
        assert!(
            app.pending_root_restore.is_none(),
            "the pending snapshot must be consumed exactly once",
        );
    }

    #[test]
    fn drain_pending_root_restore_restores_fullscreen_true_when_root_was_originally_fullscreen() {
        let mut app = ArcenApp::default();
        let ctx = egui::Context::default();
        app.pending_root_restore = Some(RootPreEntrySnapshot {
            display_id: None,
            fullscreen: Some(true),
            inner_rect_size_pts: None,
        });

        app.drain_pending_root_restore(&ctx);

        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        assert!(
            sent.contains(&egui::ViewportCommand::Fullscreen(true)),
            "an originally-fullscreen root must be restored to fullscreen: {sent:?}",
        );
    }

    #[test]
    fn drain_pending_root_restore_skips_setmonitor_when_the_original_display_id_is_no_longer_live()
    {
        let mut app = ArcenApp::default();
        let ctx = egui::Context::default();
        // A sentinel guaranteed to never match any real live display, in
        // exactly the same spirit as `FAKE_CG_DISPLAY_ID_PRIMARY` above.
        app.pending_root_restore = Some(RootPreEntrySnapshot {
            display_id: Some(0xFFFF_FFF9),
            fullscreen: Some(false),
            inner_rect_size_pts: None,
        });

        app.drain_pending_root_restore(&ctx);

        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        assert!(
            !sent
                .iter()
                .any(|command| matches!(command, egui::ViewportCommand::SetMonitor(_))),
            "a display that has disappeared must never be sent to SetMonitor: {sent:?}",
        );
        assert!(sent.contains(&egui::ViewportCommand::Fullscreen(false)));
    }

    #[test]
    fn drive_multi_window_root_unresolvable_primary_never_captures_or_restores_a_snapshot() {
        // Complement to "no command/no snapshot": root's own negotiated
        // primary can never be sent to `SetMonitor` at all here
        // (`FAKE_CG_DISPLAY_ID_PRIMARY` can never resolve on a real display
        // list), so no command is ever sent, no snapshot is ever captured,
        // and the resulting teardown (root's own unresolvable-primary hard
        // failure) must not queue any restore either.
        let mut app = ArcenApp::default();
        let validated = single_monitor_validated_topology();
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.multi_window_started_at = Some(Instant::now());

        app.drive_multi_window(&egui::Context::default());

        assert!(matches!(
            app.multi_window,
            MultiWindowSessionState::Inactive
        ));
        assert!(
            app.root_pre_entry_snapshot.is_none(),
            "an unresolvable primary must never have sent a command, so must never have \
             captured a snapshot",
        );
        assert!(
            app.pending_root_restore.is_none(),
            "no snapshot ever captured must mean no restore is ever queued",
        );
    }

    #[test]
    fn drive_multi_window_captures_and_restores_roots_pre_entry_snapshot_when_a_secondary_hard_fails(
    ) {
        // "move then secondary fail restores original display/windowed":
        // root's own negotiated primary is a real, live display (so its
        // very first `SetMonitor` actually sends and a snapshot is
        // captured), while the lone secondary is assigned a display that
        // can never be live -- an immediate hard failure that must tear
        // the whole attempt down *before* commit, restoring root via the
        // just-captured snapshot rather than stranding it wherever the
        // aborted move left it.
        let live_display_ids: Vec<u32> = crate::ui::multi_window_runtime::live_active_displays()
            .iter()
            .map(|display| display.cg_display_id)
            .collect();
        if live_display_ids.is_empty() {
            eprintln!(
                "skipping: need at least 1 live active display in this environment for root's \
                 own move command to actually resolve and send",
            );
            return;
        }
        let root_display_id = live_display_ids[0];
        const FAKE_SECONDARY_DISPLAY_ID: u32 = 0xFFFF_FFF6;

        let validated = {
            use crate::ui::multi_window_session::{
                DesktopRect, MonitorDesktopRect, ResolvedAppliedMonitor,
            };
            crate::ui::multi_window_session::ValidatedAppliedTopology {
                generation: arcen_media::TopologyGeneration::new(1).expect("valid generation"),
                carrier: crate::protocol::messages::MultiMonitorCarrierMsg::MuxedReliableStream,
                monitors: vec![
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(1)
                            .expect("valid id"),
                        cg_display_id: root_display_id,
                        rect: MonitorDesktopRect {
                            x: 0,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                    ResolvedAppliedMonitor {
                        session_monitor_id: arcen_media::SessionMonitorId::new(2)
                            .expect("valid id"),
                        cg_display_id: FAKE_SECONDARY_DISPLAY_ID,
                        rect: MonitorDesktopRect {
                            x: 1920,
                            y: 0,
                            width_px: 1920,
                            height_px: 1080,
                        },
                    },
                ],
                media_roster: test_media_roster(&[1, 2]),
                desktop: DesktopRect {
                    x: 0,
                    y: 0,
                    width_px: 3840,
                    height_px: 1080,
                },
            }
        };
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp::default();
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.multi_window_started_at = Some(Instant::now());

        let ctx = egui::Context::default();
        app.drive_multi_window(&ctx);

        assert!(
            matches!(app.multi_window, MultiWindowSessionState::Inactive),
            "the secondary's unresolvable display must hard-abort and tear down the whole \
             attempt before commit",
        );
        assert!(
            app.pending_root_restore.is_some(),
            "root's own move command must have been sent this same frame (its primary is a \
             real, resolvable display), so a pre-entry snapshot must have been captured and \
             queued for restore by the teardown this hard failure triggered",
        );

        app.drain_pending_root_restore(&ctx);

        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        // Root's own observed display/fullscreen state cannot be resolved
        // in this bare test harness (no real `Arcen Deck`-titled window is
        // open -- see `window_display_id`'s own doc), so the captured
        // snapshot's `display_id`/`fullscreen` are `None`; restoring that
        // is still meaningful: it is exactly the safe "unknown state ->
        // restore windowed" default (`root_pre_entry_snapshot_restore_commands_defaults_to_windowed_when_fullscreen_state_was_unknown`
        // proves the same default in isolation), so the observable
        // contract here is that the restore-fullscreen command was
        // actually sent and the pending snapshot was consumed.
        assert!(
            sent.contains(&egui::ViewportCommand::Fullscreen(false)),
            "must have sent root's restore command: {sent:?}",
        );
        assert!(
            app.pending_root_restore.is_none(),
            "the restore must be consumed exactly once",
        );
    }

    #[test]
    fn drive_multi_window_fails_closed_and_disconnects_when_root_notch_fullscreen_is_active() {
        // `match_layout_preflight` already refuses to negotiate real
        // multi-monitor whenever notch state could apply, so this should
        // never actually be reachable in production -- this proves the
        // defensive backstop in `drive_multi_window` itself: if
        // `notch_fullscreen_active` is somehow `true` on an `Active` attempt
        // (a race/future bug), the whole attempt is torn down with no
        // window command of any kind ever sent this frame, root's own move
        // included.
        let validated = single_monitor_validated_topology();
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp::default();
        app.multi_window = MultiWindowSessionState::Active {
            validated,
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.multi_window_started_at = Some(Instant::now());
        app.notch_fullscreen_active = true;

        let ctx = egui::Context::default();
        app.drive_multi_window(&ctx);

        assert!(
            matches!(app.multi_window, MultiWindowSessionState::Inactive),
            "an active root notch fullscreen must hard-fail-close the whole attempt",
        );
        let sent = ctx.viewport_for(egui::ViewportId::ROOT, |viewport| viewport.commands.clone());
        assert!(
            sent.is_empty(),
            "no window command (root's own move included) may ever be sent this frame: {sent:?}",
        );
        assert!(
            app.root_pre_entry_snapshot.is_none(),
            "no snapshot must ever be captured -- root's move command was never even \
             attempted, so there is nothing to have captured",
        );
    }

