    #[test]
    fn drive_multi_window_a_degenerate_single_monitor_plan_still_requires_root_to_confirm() {
        // Before root was independently tracked, a zero-assignment plan
        // (single-monitor roster: nothing else to open) committed for
        // free on its very first `drive_multi_window` poll, since nothing
        // else was ever checked. That was the exact bug: root's own
        // window was never required to confirm it actually bound the
        // negotiated primary display. This test proves the fix: even a
        // degenerate plan must hard-abort and disconnect when root's own
        // primary target (`FAKE_CG_DISPLAY_ID_PRIMARY`) can never resolve
        // on a real display list, rather than vacuously committing.
        let mut app = ArcenApp::default();
        let validated = single_monitor_validated_topology();
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        assert!(
            plan.assignments().is_empty(),
            "a single-monitor roster must plan zero additional windows",
        );
        app.multi_window = MultiWindowSessionState::Active {
            validated: validated.clone(),
            attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
            committed: false,
        };
        app.multi_window_started_at = Some(Instant::now());

        app.drive_multi_window(&egui::Context::default());

        assert!(
            matches!(app.multi_window, MultiWindowSessionState::Inactive),
            "root's own unresolvable primary target must hard-abort and disconnect rather than \
             let a degenerate (zero-secondary-window) plan commit for free",
        );
    }

