    #[test]
    fn drive_multi_window_committed_roster_loss_routes_through_multi_window_failure_not_disconnect()
    {
        // Audit finding #3: the committed-roster-loss branch must call the
        // dedicated `multi_window_failure` handler, not a silent manual
        // `disconnect()`. Proven the same way Finding #1/#2's helpers were:
        // by observing that a still-schedulable reconnect controller
        // survives and the screen lands on `Reconnecting`, not `Home` --
        // `disconnect()` unconditionally cancels the controller and never
        // does either.
        let generation = 4;
        let validated = single_monitor_validated_topology();
        let plan = crate::ui::multi_window_runtime::MultiWindowPlan::build(
            &validated.monitor_ids(),
            &validated.cg_display_ids(),
        )
        .expect("valid plan");
        let mut app = ArcenApp {
            connection_generation: generation,
            reconnect: Some(schedule_capable_reconnect_controller(generation)),
            screen: AppScreen::InSession,
            multi_window: MultiWindowSessionState::Active {
                validated,
                attempt: MultiWindowEnterAttempt::new(plan, Duration::ZERO),
                committed: true,
            },
            multi_window_started_at: Some(Instant::now()),
            ..ArcenApp::default()
        };

        app.drive_multi_window(&egui::Context::default());

        assert!(matches!(
            app.multi_window,
            MultiWindowSessionState::Inactive
        ));
        assert!(
            matches!(app.screen, AppScreen::Reconnecting(_)),
            "expected Reconnecting (reconnect preserved), got {:?}",
            app.screen
        );
        assert!(!matches!(app.screen, AppScreen::InSession));
        assert!(app.reconnect.is_some());
    }

